INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Single Choice','Easy',1,'താഴെ നൽകിയ വിവരണവുമായി ഏറ്റവും യോജിക്കുന്ന ആശയം ഏതാണ്? കമ്പ്യൂട്ടർ സംവിധാനങ്ങളെയും ശൃംഖലകളെയും ഡിജിറ്റൽ ഭീഷണികളിൽ നിന്ന് സംരക്ഷിക്കുന്ന പ്രവർത്തനം.',ARRAY['സൈബർ സുരക്ഷ','കൃമി','സാമൂഹിക എഞ്ചിനീയറിംഗ്','ആക്രമണ തടയൽ'],'സൈബർ സുരക്ഷ','ശരിയായ ഉത്തരം സൈബർ സുരക്ഷ ആണ്. കമ്പ്യൂട്ടർ സംവിധാനങ്ങളെയും ശൃംഖലകളെയും ഡിജിറ്റൽ ഭീഷണികളിൽ നിന്ന് സംരക്ഷിക്കുന്ന പ്രവർത്തനം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Single Choice','Easy',1,'താഴെ നൽകിയ വിവരണവുമായി ഏറ്റവും യോജിക്കുന്ന ആശയം ഏതാണ്? വിവരങ്ങളുടെ രഹസ്യത സമഗ്രത ലഭ്യത എന്നിവ സംരക്ഷിക്കുന്ന ശാസ്ത്രശാഖ.',ARRAY['വിവര സുരക്ഷ','ട്രോജൻ','പാസ്‌വേഡ് ആക്രമണം','വിപിഎൻ'],'വിവര സുരക്ഷ','ശരിയായ ഉത്തരം വിവര സുരക്ഷ ആണ്. വിവരങ്ങളുടെ രഹസ്യത സമഗ്രത ലഭ്യത എന്നിവ സംരക്ഷിക്കുന്ന ശാസ്ത്രശാഖ.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Single Choice','Easy',1,'താഴെ നൽകിയ വിവരണവുമായി ഏറ്റവും യോജിക്കുന്ന ആശയം ഏതാണ്? അനുമതിയുള്ള വ്യക്തികൾക്ക് മാത്രം വിവരങ്ങൾ ലഭ്യമാകുന്ന ഗുണം.',ARRAY['രഹസ്യത','റാൻസംവെയർ','ബ്രൂട്ട് ഫോഴ്‌സ് ആക്രമണം','എൻക്രിപ്ഷൻ'],'രഹസ്യത','ശരിയായ ഉത്തരം രഹസ്യത ആണ്. അനുമതിയുള്ള വ്യക്തികൾക്ക് മാത്രം വിവരങ്ങൾ ലഭ്യമാകുന്ന ഗുണം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Single Choice','Easy',1,'താഴെ നൽകിയ വിവരണവുമായി ഏറ്റവും യോജിക്കുന്ന ആശയം ഏതാണ്? വിവരങ്ങൾ അനധികൃതമായി മാറ്റപ്പെടാതിരിക്കുന്ന ഗുണം.',ARRAY['സമഗ്രത','ചാര സോഫ്റ്റ്‌വെയർ','ബഹുഘടക തിരിച്ചറിയൽ','ഡീക്രിപ്ഷൻ'],'സമഗ്രത','ശരിയായ ഉത്തരം സമഗ്രത ആണ്. വിവരങ്ങൾ അനധികൃതമായി മാറ്റപ്പെടാതിരിക്കുന്ന ഗുണം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Single Choice','Easy',1,'താഴെ നൽകിയ വിവരണവുമായി ഏറ്റവും യോജിക്കുന്ന ആശയം ഏതാണ്? അധികാരമുള്ള ഉപയോക്താക്കൾക്ക് ആവശ്യസമയത്ത് വിഭവം ലഭിക്കുന്ന ഗുണം.',ARRAY['ലഭ്യത','ഫിഷിംഗ്','അനുമതി നിയന്ത്രണം','ഹാഷിംഗ്'],'ലഭ്യത','ശരിയായ ഉത്തരം ലഭ്യത ആണ്. അധികാരമുള്ള ഉപയോക്താക്കൾക്ക് ആവശ്യസമയത്ത് വിഭവം ലഭിക്കുന്ന ഗുണം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Single Choice','Easy',1,'താഴെ നൽകിയ വിവരണവുമായി ഏറ്റവും യോജിക്കുന്ന ആശയം ഏതാണ്? കമ്പ്യൂട്ടർ സംവിധാനത്തിന് ദോഷം ചെയ്യാനോ അനധികൃത പ്രവർത്തനം നടത്താനോ രൂപകൽപ്പന ചെയ്ത സോഫ്റ്റ്‌വെയർ.',ARRAY['ക്ഷുദ്ര സോഫ്റ്റ്‌വെയർ','വഞ്ചനാ സന്ദേശം','തിരിച്ചറിയൽ പരിശോധന','ഡിജിറ്റൽ ഒപ്പ്'],'ക്ഷുദ്ര സോഫ്റ്റ്‌വെയർ','ശരിയായ ഉത്തരം ക്ഷുദ്ര സോഫ്റ്റ്‌വെയർ ആണ്. കമ്പ്യൂട്ടർ സംവിധാനത്തിന് ദോഷം ചെയ്യാനോ അനധികൃത പ്രവർത്തനം നടത്താനോ രൂപകൽപ്പന ചെയ്ത സോഫ്റ്റ്‌വെയർ.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Single Choice','Easy',1,'താഴെ നൽകിയ വിവരണവുമായി ഏറ്റവും യോജിക്കുന്ന ആശയം ഏതാണ്? മറ്റൊരു പ്രോഗ്രാമിൽ ചേർന്ന് വ്യാപിക്കുന്ന ക്ഷുദ്ര പ്രോഗ്രാം.',ARRAY['വൈറസ്','സാമൂഹിക എഞ്ചിനീയറിംഗ്','അഗ്നിരോധ മതിൽ','സർട്ടിഫിക്കറ്റ്'],'വൈറസ്','ശരിയായ ഉത്തരം വൈറസ് ആണ്. മറ്റൊരു പ്രോഗ്രാമിൽ ചേർന്ന് വ്യാപിക്കുന്ന ക്ഷുദ്ര പ്രോഗ്രാം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Single Choice','Easy',1,'താഴെ നൽകിയ വിവരണവുമായി ഏറ്റവും യോജിക്കുന്ന ആശയം ഏതാണ്? സ്വയം പകർത്തി ശൃംഖലകളിലൂടെ വ്യാപിക്കാൻ കഴിയുന്ന ക്ഷുദ്ര പ്രോഗ്രാം.',ARRAY['കൃമി','പാസ്‌വേഡ് ആക്രമണം','ആക്രമണ കണ്ടെത്തൽ','സുരക്ഷാ ദൗർബല്യം'],'കൃമി','ശരിയായ ഉത്തരം കൃമി ആണ്. സ്വയം പകർത്തി ശൃംഖലകളിലൂടെ വ്യാപിക്കാൻ കഴിയുന്ന ക്ഷുദ്ര പ്രോഗ്രാം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Single Choice','Easy',1,'താഴെ നൽകിയ വിവരണവുമായി ഏറ്റവും യോജിക്കുന്ന ആശയം ഏതാണ്? ഉപകാരപ്രദമായ പ്രോഗ്രാമെന്ന ഭാവത്തിൽ മറഞ്ഞിരിക്കുന്ന ക്ഷുദ്ര സോഫ്റ്റ്‌വെയർ.',ARRAY['ട്രോജൻ','ബ്രൂട്ട് ഫോഴ്‌സ് ആക്രമണം','ആക്രമണ തടയൽ','ഭീഷണി'],'ട്രോജൻ','ശരിയായ ഉത്തരം ട്രോജൻ ആണ്. ഉപകാരപ്രദമായ പ്രോഗ്രാമെന്ന ഭാവത്തിൽ മറഞ്ഞിരിക്കുന്ന ക്ഷുദ്ര സോഫ്റ്റ്‌വെയർ.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Single Choice','Easy',1,'താഴെ നൽകിയ വിവരണവുമായി ഏറ്റവും യോജിക്കുന്ന ആശയം ഏതാണ്? ഡാറ്റ പൂട്ടിയ ശേഷം മോചനത്തുക ആവശ്യപ്പെടുന്ന ക്ഷുദ്ര സോഫ്റ്റ്‌വെയർ.',ARRAY['റാൻസംവെയർ','ബഹുഘടക തിരിച്ചറിയൽ','വിപിഎൻ','അപകടസാധ്യത'],'റാൻസംവെയർ','ശരിയായ ഉത്തരം റാൻസംവെയർ ആണ്. ഡാറ്റ പൂട്ടിയ ശേഷം മോചനത്തുക ആവശ്യപ്പെടുന്ന ക്ഷുദ്ര സോഫ്റ്റ്‌വെയർ.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Single Choice','Easy',1,'താഴെ നൽകിയ വിവരണവുമായി ഏറ്റവും യോജിക്കുന്ന ആശയം ഏതാണ്? ഉപയോക്താവിന്റെ പ്രവർത്തനങ്ങൾ രഹസ്യമായി നിരീക്ഷിക്കുന്ന ക്ഷുദ്ര സോഫ്റ്റ്‌വെയർ.',ARRAY['ചാര സോഫ്റ്റ്‌വെയർ','അനുമതി നിയന്ത്രണം','എൻക്രിപ്ഷൻ','സുരക്ഷാ പരിശോധന'],'ചാര സോഫ്റ്റ്‌വെയർ','ശരിയായ ഉത്തരം ചാര സോഫ്റ്റ്‌വെയർ ആണ്. ഉപയോക്താവിന്റെ പ്രവർത്തനങ്ങൾ രഹസ്യമായി നിരീക്ഷിക്കുന്ന ക്ഷുദ്ര സോഫ്റ്റ്‌വെയർ.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Single Choice','Easy',1,'താഴെ നൽകിയ വിവരണവുമായി ഏറ്റവും യോജിക്കുന്ന ആശയം ഏതാണ്? വ്യാജ സന്ദേശങ്ങളിലൂടെ രഹസ്യ വിവരങ്ങൾ നേടാനുള്ള തട്ടിപ്പ് രീതി.',ARRAY['ഫിഷിംഗ്','തിരിച്ചറിയൽ പരിശോധന','ഡീക്രിപ്ഷൻ','പ്രവേശന പരിശോധന'],'ഫിഷിംഗ്','ശരിയായ ഉത്തരം ഫിഷിംഗ് ആണ്. വ്യാജ സന്ദേശങ്ങളിലൂടെ രഹസ്യ വിവരങ്ങൾ നേടാനുള്ള തട്ടിപ്പ് രീതി.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Single Choice','Easy',1,'താഴെ നൽകിയ വിവരണവുമായി ഏറ്റവും യോജിക്കുന്ന ആശയം ഏതാണ്? വിശ്വസനീയ ഉറവിടമെന്ന വ്യാജേന ഉപയോക്താവിനെ തെറ്റിദ്ധരിപ്പിക്കുന്ന സന്ദേശം.',ARRAY['വഞ്ചനാ സന്ദേശം','അഗ്നിരോധ മതിൽ','ഹാഷിംഗ്','ലോഗ് നിരീക്ഷണം'],'വഞ്ചനാ സന്ദേശം','ശരിയായ ഉത്തരം വഞ്ചനാ സന്ദേശം ആണ്. വിശ്വസനീയ ഉറവിടമെന്ന വ്യാജേന ഉപയോക്താവിനെ തെറ്റിദ്ധരിപ്പിക്കുന്ന സന്ദേശം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Single Choice','Easy',1,'താഴെ നൽകിയ വിവരണവുമായി ഏറ്റവും യോജിക്കുന്ന ആശയം ഏതാണ്? മനുഷ്യരുടെ വിശ്വാസവും പെരുമാറ്റവും ചൂഷണം ചെയ്ത് വിവരങ്ങൾ നേടുന്ന രീതി.',ARRAY['സാമൂഹിക എഞ്ചിനീയറിംഗ്','ആക്രമണ കണ്ടെത്തൽ','ഡിജിറ്റൽ ഒപ്പ്','സംഭവ പ്രതികരണം'],'സാമൂഹിക എഞ്ചിനീയറിംഗ്','ശരിയായ ഉത്തരം സാമൂഹിക എഞ്ചിനീയറിംഗ് ആണ്. മനുഷ്യരുടെ വിശ്വാസവും പെരുമാറ്റവും ചൂഷണം ചെയ്ത് വിവരങ്ങൾ നേടുന്ന രീതി.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Single Choice','Easy',1,'താഴെ നൽകിയ വിവരണവുമായി ഏറ്റവും യോജിക്കുന്ന ആശയം ഏതാണ്? പാസ്‌വേഡ് കണ്ടെത്താനോ മറികടക്കാനോ നടത്തുന്ന ആക്രമണം.',ARRAY['പാസ്‌വേഡ് ആക്രമണം','ആക്രമണ തടയൽ','സർട്ടിഫിക്കറ്റ്','ഡാറ്റ ചോർച്ച'],'പാസ്‌വേഡ് ആക്രമണം','ശരിയായ ഉത്തരം പാസ്‌വേഡ് ആക്രമണം ആണ്. പാസ്‌വേഡ് കണ്ടെത്താനോ മറികടക്കാനോ നടത്തുന്ന ആക്രമണം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Single Choice','Easy',1,'താഴെ നൽകിയ വിവരണവുമായി ഏറ്റവും യോജിക്കുന്ന ആശയം ഏതാണ്? സാധ്യമായ നിരവധി പാസ്‌വേഡുകൾ പരീക്ഷിക്കുന്ന ആക്രമണ രീതി.',ARRAY['ബ്രൂട്ട് ഫോഴ്‌സ് ആക്രമണം','വിപിഎൻ','സുരക്ഷാ ദൗർബല്യം','ബാക്കപ്പ്'],'ബ്രൂട്ട് ഫോഴ്‌സ് ആക്രമണം','ശരിയായ ഉത്തരം ബ്രൂട്ട് ഫോഴ്‌സ് ആക്രമണം ആണ്. സാധ്യമായ നിരവധി പാസ്‌വേഡുകൾ പരീക്ഷിക്കുന്ന ആക്രമണ രീതി.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Single Choice','Easy',1,'താഴെ നൽകിയ വിവരണവുമായി ഏറ്റവും യോജിക്കുന്ന ആശയം ഏതാണ്? ഒന്നിലധികം തിരിച്ചറിയൽ തെളിവുകൾ ഉപയോഗിക്കുന്ന സുരക്ഷാ രീതി.',ARRAY['ബഹുഘടക തിരിച്ചറിയൽ','എൻക്രിപ്ഷൻ','ഭീഷണി','ദുരന്ത വീണ്ടെടുക്കൽ'],'ബഹുഘടക തിരിച്ചറിയൽ','ശരിയായ ഉത്തരം ബഹുഘടക തിരിച്ചറിയൽ ആണ്. ഒന്നിലധികം തിരിച്ചറിയൽ തെളിവുകൾ ഉപയോഗിക്കുന്ന സുരക്ഷാ രീതി.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Single Choice','Easy',1,'താഴെ നൽകിയ വിവരണവുമായി ഏറ്റവും യോജിക്കുന്ന ആശയം ഏതാണ്? ഉപയോക്താക്കൾക്ക് അനുവദിച്ച പ്രവർത്തനങ്ങൾ മാത്രം നടത്താൻ സഹായിക്കുന്ന സംവിധാനം.',ARRAY['അനുമതി നിയന്ത്രണം','ഡീക്രിപ്ഷൻ','അപകടസാധ്യത','സുരക്ഷാ ബോധവൽക്കരണം'],'അനുമതി നിയന്ത്രണം','ശരിയായ ഉത്തരം അനുമതി നിയന്ത്രണം ആണ്. ഉപയോക്താക്കൾക്ക് അനുവദിച്ച പ്രവർത്തനങ്ങൾ മാത്രം നടത്താൻ സഹായിക്കുന്ന സംവിധാനം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Single Choice','Easy',1,'താഴെ നൽകിയ വിവരണവുമായി ഏറ്റവും യോജിക്കുന്ന ആശയം ഏതാണ്? ഉപയോക്താവിന്റെ തിരിച്ചറിയൽ ശരിയാണെന്ന് സ്ഥിരീകരിക്കുന്ന പ്രക്രിയ.',ARRAY['തിരിച്ചറിയൽ പരിശോധന','ഹാഷിംഗ്','സുരക്ഷാ പരിശോധന','സുരക്ഷാ നയം'],'തിരിച്ചറിയൽ പരിശോധന','ശരിയായ ഉത്തരം തിരിച്ചറിയൽ പരിശോധന ആണ്. ഉപയോക്താവിന്റെ തിരിച്ചറിയൽ ശരിയാണെന്ന് സ്ഥിരീകരിക്കുന്ന പ്രക്രിയ.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Single Choice','Easy',1,'താഴെ നൽകിയ വിവരണവുമായി ഏറ്റവും യോജിക്കുന്ന ആശയം ഏതാണ്? അനുവദിക്കാത്ത ശൃംഖലാ ബന്ധങ്ങൾ തടയുന്ന സുരക്ഷാ സംവിധാനം.',ARRAY['അഗ്നിരോധ മതിൽ','ഡിജിറ്റൽ ഒപ്പ്','പ്രവേശന പരിശോധന','സൈബർ സുരക്ഷ'],'അഗ്നിരോധ മതിൽ','ശരിയായ ഉത്തരം അഗ്നിരോധ മതിൽ ആണ്. അനുവദിക്കാത്ത ശൃംഖലാ ബന്ധങ്ങൾ തടയുന്ന സുരക്ഷാ സംവിധാനം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Single Choice','Easy',1,'താഴെ നൽകിയ വിവരണവുമായി ഏറ്റവും യോജിക്കുന്ന ആശയം ഏതാണ്? സംശയാസ്പദമായ ശൃംഖലാ പ്രവർത്തനങ്ങൾ കണ്ടെത്തുന്ന സംവിധാനം.',ARRAY['ആക്രമണ കണ്ടെത്തൽ','സർട്ടിഫിക്കറ്റ്','ലോഗ് നിരീക്ഷണം','വിവര സുരക്ഷ'],'ആക്രമണ കണ്ടെത്തൽ','ശരിയായ ഉത്തരം ആക്രമണ കണ്ടെത്തൽ ആണ്. സംശയാസ്പദമായ ശൃംഖലാ പ്രവർത്തനങ്ങൾ കണ്ടെത്തുന്ന സംവിധാനം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Single Choice','Easy',1,'താഴെ നൽകിയ വിവരണവുമായി ഏറ്റവും യോജിക്കുന്ന ആശയം ഏതാണ്? സംശയാസ്പദമായ പ്രവർത്തനങ്ങൾ കണ്ടെത്തുകയും തടയുകയും ചെയ്യുന്ന സംവിധാനം.',ARRAY['ആക്രമണ തടയൽ','സുരക്ഷാ ദൗർബല്യം','സംഭവ പ്രതികരണം','രഹസ്യത'],'ആക്രമണ തടയൽ','ശരിയായ ഉത്തരം ആക്രമണ തടയൽ ആണ്. സംശയാസ്പദമായ പ്രവർത്തനങ്ങൾ കണ്ടെത്തുകയും തടയുകയും ചെയ്യുന്ന സംവിധാനം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Single Choice','Easy',1,'താഴെ നൽകിയ വിവരണവുമായി ഏറ്റവും യോജിക്കുന്ന ആശയം ഏതാണ്? സുരക്ഷിതമായ സ്വകാര്യ ബന്ധം സൃഷ്ടിക്കുന്ന ശൃംഖലാ സാങ്കേതികവിദ്യ.',ARRAY['വിപിഎൻ','ഭീഷണി','ഡാറ്റ ചോർച്ച','സമഗ്രത'],'വിപിഎൻ','ശരിയായ ഉത്തരം വിപിഎൻ ആണ്. സുരക്ഷിതമായ സ്വകാര്യ ബന്ധം സൃഷ്ടിക്കുന്ന ശൃംഖലാ സാങ്കേതികവിദ്യ.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Single Choice','Easy',1,'താഴെ നൽകിയ വിവരണവുമായി ഏറ്റവും യോജിക്കുന്ന ആശയം ഏതാണ്? വിവരങ്ങളെ സംരക്ഷിത രൂപത്തിലേക്ക് മാറ്റുന്ന പ്രക്രിയ.',ARRAY['എൻക്രിപ്ഷൻ','അപകടസാധ്യത','ബാക്കപ്പ്','ലഭ്യത'],'എൻക്രിപ്ഷൻ','ശരിയായ ഉത്തരം എൻക്രിപ്ഷൻ ആണ്. വിവരങ്ങളെ സംരക്ഷിത രൂപത്തിലേക്ക് മാറ്റുന്ന പ്രക്രിയ.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Single Choice','Easy',1,'താഴെ നൽകിയ വിവരണവുമായി ഏറ്റവും യോജിക്കുന്ന ആശയം ഏതാണ്? സംരക്ഷിത രൂപത്തിലുള്ള വിവരങ്ങളെ വായിക്കാവുന്ന രൂപത്തിലേക്ക് മാറ്റുന്ന പ്രക്രിയ.',ARRAY['ഡീക്രിപ്ഷൻ','സുരക്ഷാ പരിശോധന','ദുരന്ത വീണ്ടെടുക്കൽ','ക്ഷുദ്ര സോഫ്റ്റ്‌വെയർ'],'ഡീക്രിപ്ഷൻ','ശരിയായ ഉത്തരം ഡീക്രിപ്ഷൻ ആണ്. സംരക്ഷിത രൂപത്തിലുള്ള വിവരങ്ങളെ വായിക്കാവുന്ന രൂപത്തിലേക്ക് മാറ്റുന്ന പ്രക്രിയ.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Single Choice','Easy',1,'താഴെ നൽകിയ വിവരണവുമായി ഏറ്റവും യോജിക്കുന്ന ആശയം ഏതാണ്? ഡാറ്റയ്ക്ക് നിശ്ചിത നീളത്തിലുള്ള പ്രതിനിധി മൂല്യം സൃഷ്ടിക്കുന്ന ഏകദിശാ രീതി.',ARRAY['ഹാഷിംഗ്','പ്രവേശന പരിശോധന','സുരക്ഷാ ബോധവൽക്കരണം','വൈറസ്'],'ഹാഷിംഗ്','ശരിയായ ഉത്തരം ഹാഷിംഗ് ആണ്. ഡാറ്റയ്ക്ക് നിശ്ചിത നീളത്തിലുള്ള പ്രതിനിധി മൂല്യം സൃഷ്ടിക്കുന്ന ഏകദിശാ രീതി.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Single Choice','Easy',1,'താഴെ നൽകിയ വിവരണവുമായി ഏറ്റവും യോജിക്കുന്ന ആശയം ഏതാണ്? ഡിജിറ്റൽ രേഖയുടെ ഉറവിടവും സമഗ്രതയും പരിശോധിക്കാൻ ഉപയോഗിക്കുന്ന സുരക്ഷാ രീതി.',ARRAY['ഡിജിറ്റൽ ഒപ്പ്','ലോഗ് നിരീക്ഷണം','സുരക്ഷാ നയം','കൃമി'],'ഡിജിറ്റൽ ഒപ്പ്','ശരിയായ ഉത്തരം ഡിജിറ്റൽ ഒപ്പ് ആണ്. ഡിജിറ്റൽ രേഖയുടെ ഉറവിടവും സമഗ്രതയും പരിശോധിക്കാൻ ഉപയോഗിക്കുന്ന സുരക്ഷാ രീതി.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Single Choice','Easy',1,'താഴെ നൽകിയ വിവരണവുമായി ഏറ്റവും യോജിക്കുന്ന ആശയം ഏതാണ്? ഡിജിറ്റൽ തിരിച്ചറിയലുമായി ബന്ധപ്പെട്ട വിശ്വാസയോഗ്യമായ രേഖ.',ARRAY['സർട്ടിഫിക്കറ്റ്','സംഭവ പ്രതികരണം','സൈബർ സുരക്ഷ','ട്രോജൻ'],'സർട്ടിഫിക്കറ്റ്','ശരിയായ ഉത്തരം സർട്ടിഫിക്കറ്റ് ആണ്. ഡിജിറ്റൽ തിരിച്ചറിയലുമായി ബന്ധപ്പെട്ട വിശ്വാസയോഗ്യമായ രേഖ.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Single Choice','Easy',1,'താഴെ നൽകിയ വിവരണവുമായി ഏറ്റവും യോജിക്കുന്ന ആശയം ഏതാണ്? ഒരു സംവിധാനത്തെ ആക്രമണത്തിന് വിധേയമാക്കാവുന്ന ബലഹീനത.',ARRAY['സുരക്ഷാ ദൗർബല്യം','ഡാറ്റ ചോർച്ച','വിവര സുരക്ഷ','റാൻസംവെയർ'],'സുരക്ഷാ ദൗർബല്യം','ശരിയായ ഉത്തരം സുരക്ഷാ ദൗർബല്യം ആണ്. ഒരു സംവിധാനത്തെ ആക്രമണത്തിന് വിധേയമാക്കാവുന്ന ബലഹീനത.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Single Choice','Easy',1,'താഴെ നൽകിയ വിവരണവുമായി ഏറ്റവും യോജിക്കുന്ന ആശയം ഏതാണ്? സുരക്ഷയ്ക്ക് ദോഷം വരുത്താൻ സാധ്യതയുള്ള സാഹചര്യമോ പ്രവർത്തനമോ.',ARRAY['ഭീഷണി','ബാക്കപ്പ്','രഹസ്യത','ചാര സോഫ്റ്റ്‌വെയർ'],'ഭീഷണി','ശരിയായ ഉത്തരം ഭീഷണി ആണ്. സുരക്ഷയ്ക്ക് ദോഷം വരുത്താൻ സാധ്യതയുള്ള സാഹചര്യമോ പ്രവർത്തനമോ.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Single Choice','Easy',1,'താഴെ നൽകിയ വിവരണവുമായി ഏറ്റവും യോജിക്കുന്ന ആശയം ഏതാണ്? ഒരു ഭീഷണി ദൗർബല്യം ഉപയോഗപ്പെടുത്തുന്നതിലൂടെ ഉണ്ടാകാവുന്ന നഷ്ടസാധ്യത.',ARRAY['അപകടസാധ്യത','ദുരന്ത വീണ്ടെടുക്കൽ','സമഗ്രത','ഫിഷിംഗ്'],'അപകടസാധ്യത','ശരിയായ ഉത്തരം അപകടസാധ്യത ആണ്. ഒരു ഭീഷണി ദൗർബല്യം ഉപയോഗപ്പെടുത്തുന്നതിലൂടെ ഉണ്ടാകാവുന്ന നഷ്ടസാധ്യത.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Single Choice','Easy',1,'താഴെ നൽകിയ വിവരണവുമായി ഏറ്റവും യോജിക്കുന്ന ആശയം ഏതാണ്? സംവിധാനത്തിലെ ദൗർബല്യങ്ങൾ കണ്ടെത്തുന്നതിനുള്ള ക്രമബദ്ധമായ പരിശോധന.',ARRAY['സുരക്ഷാ പരിശോധന','സുരക്ഷാ ബോധവൽക്കരണം','ലഭ്യത','വഞ്ചനാ സന്ദേശം'],'സുരക്ഷാ പരിശോധന','ശരിയായ ഉത്തരം സുരക്ഷാ പരിശോധന ആണ്. സംവിധാനത്തിലെ ദൗർബല്യങ്ങൾ കണ്ടെത്തുന്നതിനുള്ള ക്രമബദ്ധമായ പരിശോധന.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Single Choice','Easy',1,'താഴെ നൽകിയ വിവരണവുമായി ഏറ്റവും യോജിക്കുന്ന ആശയം ഏതാണ്? സുരക്ഷാ നിയന്ത്രണങ്ങളെ പരീക്ഷിക്കാൻ അനുമതിയോടെ നടത്തുന്ന ആക്രമണ മാതൃകാ പരിശോധന.',ARRAY['പ്രവേശന പരിശോധന','സുരക്ഷാ നയം','ക്ഷുദ്ര സോഫ്റ്റ്‌വെയർ','സാമൂഹിക എഞ്ചിനീയറിംഗ്'],'പ്രവേശന പരിശോധന','ശരിയായ ഉത്തരം പ്രവേശന പരിശോധന ആണ്. സുരക്ഷാ നിയന്ത്രണങ്ങളെ പരീക്ഷിക്കാൻ അനുമതിയോടെ നടത്തുന്ന ആക്രമണ മാതൃകാ പരിശോധന.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Single Choice','Easy',1,'താഴെ നൽകിയ വിവരണവുമായി ഏറ്റവും യോജിക്കുന്ന ആശയം ഏതാണ്? സംവിധാന പ്രവർത്തനങ്ങളുടെ രേഖകൾ പരിശോധിച്ച് അസാധാരണത കണ്ടെത്തുന്ന പ്രവർത്തനം.',ARRAY['ലോഗ് നിരീക്ഷണം','സൈബർ സുരക്ഷ','വൈറസ്','പാസ്‌വേഡ് ആക്രമണം'],'ലോഗ് നിരീക്ഷണം','ശരിയായ ഉത്തരം ലോഗ് നിരീക്ഷണം ആണ്. സംവിധാന പ്രവർത്തനങ്ങളുടെ രേഖകൾ പരിശോധിച്ച് അസാധാരണത കണ്ടെത്തുന്ന പ്രവർത്തനം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Single Choice','Easy',1,'താഴെ നൽകിയ വിവരണവുമായി ഏറ്റവും യോജിക്കുന്ന ആശയം ഏതാണ്? സുരക്ഷാ സംഭവത്തെ തിരിച്ചറിഞ്ഞ് നിയന്ത്രിക്കുകയും പരിഹരിക്കുകയും ചെയ്യുന്ന പ്രക്രിയ.',ARRAY['സംഭവ പ്രതികരണം','വിവര സുരക്ഷ','കൃമി','ബ്രൂട്ട് ഫോഴ്‌സ് ആക്രമണം'],'സംഭവ പ്രതികരണം','ശരിയായ ഉത്തരം സംഭവ പ്രതികരണം ആണ്. സുരക്ഷാ സംഭവത്തെ തിരിച്ചറിഞ്ഞ് നിയന്ത്രിക്കുകയും പരിഹരിക്കുകയും ചെയ്യുന്ന പ്രക്രിയ.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Single Choice','Easy',1,'താഴെ നൽകിയ വിവരണവുമായി ഏറ്റവും യോജിക്കുന്ന ആശയം ഏതാണ്? അനുമതിയില്ലാത്ത വ്യക്തികൾക്ക് സംരക്ഷിത വിവരങ്ങൾ ലഭിക്കുന്ന സംഭവം.',ARRAY['ഡാറ്റ ചോർച്ച','രഹസ്യത','ട്രോജൻ','ബഹുഘടക തിരിച്ചറിയൽ'],'ഡാറ്റ ചോർച്ച','ശരിയായ ഉത്തരം ഡാറ്റ ചോർച്ച ആണ്. അനുമതിയില്ലാത്ത വ്യക്തികൾക്ക് സംരക്ഷിത വിവരങ്ങൾ ലഭിക്കുന്ന സംഭവം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Single Choice','Easy',1,'താഴെ നൽകിയ വിവരണവുമായി ഏറ്റവും യോജിക്കുന്ന ആശയം ഏതാണ്? നഷ്ടപ്പെട്ട ഡാറ്റ വീണ്ടെടുക്കുന്നതിനായി സൂക്ഷിക്കുന്ന പകർപ്പ്.',ARRAY['ബാക്കപ്പ്','സമഗ്രത','റാൻസംവെയർ','അനുമതി നിയന്ത്രണം'],'ബാക്കപ്പ്','ശരിയായ ഉത്തരം ബാക്കപ്പ് ആണ്. നഷ്ടപ്പെട്ട ഡാറ്റ വീണ്ടെടുക്കുന്നതിനായി സൂക്ഷിക്കുന്ന പകർപ്പ്.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Single Choice','Easy',1,'താഴെ നൽകിയ വിവരണവുമായി ഏറ്റവും യോജിക്കുന്ന ആശയം ഏതാണ്? വലിയ സുരക്ഷാ സംഭവത്തിന് ശേഷം സംവിധാനങ്ങളെ പുനഃസ്ഥാപിക്കുന്ന പദ്ധതി.',ARRAY['ദുരന്ത വീണ്ടെടുക്കൽ','ലഭ്യത','ചാര സോഫ്റ്റ്‌വെയർ','തിരിച്ചറിയൽ പരിശോധന'],'ദുരന്ത വീണ്ടെടുക്കൽ','ശരിയായ ഉത്തരം ദുരന്ത വീണ്ടെടുക്കൽ ആണ്. വലിയ സുരക്ഷാ സംഭവത്തിന് ശേഷം സംവിധാനങ്ങളെ പുനഃസ്ഥാപിക്കുന്ന പദ്ധതി.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Single Choice','Easy',1,'താഴെ നൽകിയ വിവരണവുമായി ഏറ്റവും യോജിക്കുന്ന ആശയം ഏതാണ്? ഉപയോക്താക്കളെ സുരക്ഷിതമായ ഡിജിറ്റൽ പെരുമാറ്റത്തെക്കുറിച്ച് പരിശീലിപ്പിക്കുന്ന പ്രവർത്തനം.',ARRAY['സുരക്ഷാ ബോധവൽക്കരണം','ക്ഷുദ്ര സോഫ്റ്റ്‌വെയർ','ഫിഷിംഗ്','അഗ്നിരോധ മതിൽ'],'സുരക്ഷാ ബോധവൽക്കരണം','ശരിയായ ഉത്തരം സുരക്ഷാ ബോധവൽക്കരണം ആണ്. ഉപയോക്താക്കളെ സുരക്ഷിതമായ ഡിജിറ്റൽ പെരുമാറ്റത്തെക്കുറിച്ച് പരിശീലിപ്പിക്കുന്ന പ്രവർത്തനം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Single Choice','Easy',1,'താഴെ നൽകിയ വിവരണവുമായി ഏറ്റവും യോജിക്കുന്ന ആശയം ഏതാണ്? ഒരു സ്ഥാപനത്തിന്റെ സുരക്ഷാ നിയമങ്ങളും ഉത്തരവാദിത്തങ്ങളും വ്യക്തമാക്കുന്ന രേഖ.',ARRAY['സുരക്ഷാ നയം','വൈറസ്','വഞ്ചനാ സന്ദേശം','ആക്രമണ കണ്ടെത്തൽ'],'സുരക്ഷാ നയം','ശരിയായ ഉത്തരം സുരക്ഷാ നയം ആണ്. ഒരു സ്ഥാപനത്തിന്റെ സുരക്ഷാ നിയമങ്ങളും ഉത്തരവാദിത്തങ്ങളും വ്യക്തമാക്കുന്ന രേഖ.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Multiple Choice','Medium',2,'താഴെപ്പറയുന്നവയിൽ സൈബർ സുരക്ഷയും വിവര സുരക്ഷയും സംബന്ധിച്ച് ശരിയായ പ്രസ്താവനകൾ തിരഞ്ഞെടുക്കുക.',ARRAY['സൈബർ സുരക്ഷ: കമ്പ്യൂട്ടർ സംവിധാനങ്ങളെയും ശൃംഖലകളെയും ഡിജിറ്റൽ ഭീഷണികളിൽ നിന്ന് സംരക്ഷിക്കുന്ന പ്രവർത്തനം','വിവര സുരക്ഷ: വിവരങ്ങളുടെ രഹസ്യത സമഗ്രത ലഭ്യത എന്നിവ സംരക്ഷിക്കുന്ന ശാസ്ത്രശാഖ','രഹസ്യത: അനുമതിയുള്ള വ്യക്തികൾക്ക് മാത്രം വിവരങ്ങൾ ലഭ്യമാകുന്ന ഗുണം','ഫിഷിംഗ്: വ്യാജ സന്ദേശങ്ങളിലൂടെ രഹസ്യ വിവരങ്ങൾ നേടാനുള്ള തട്ടിപ്പ് രീതി'],'സൈബർ സുരക്ഷ; വിവര സുരക്ഷ','സൈബർ സുരക്ഷ: കമ്പ്യൂട്ടർ സംവിധാനങ്ങളെയും ശൃംഖലകളെയും ഡിജിറ്റൽ ഭീഷണികളിൽ നിന്ന് സംരക്ഷിക്കുന്ന പ്രവർത്തനം. വിവര സുരക്ഷ: വിവരങ്ങളുടെ രഹസ്യത സമഗ്രത ലഭ്യത എന്നിവ സംരക്ഷിക്കുന്ന ശാസ്ത്രശാഖ.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Multiple Choice','Medium',2,'താഴെപ്പറയുന്നവയിൽ വിവര സുരക്ഷയും രഹസ്യതയും സംബന്ധിച്ച് ശരിയായ പ്രസ്താവനകൾ തിരഞ്ഞെടുക്കുക.',ARRAY['വിവര സുരക്ഷ: വിവരങ്ങളുടെ രഹസ്യത സമഗ്രത ലഭ്യത എന്നിവ സംരക്ഷിക്കുന്ന ശാസ്ത്രശാഖ','രഹസ്യത: അനുമതിയുള്ള വ്യക്തികൾക്ക് മാത്രം വിവരങ്ങൾ ലഭ്യമാകുന്ന ഗുണം','സമഗ്രത: വിവരങ്ങൾ അനധികൃതമായി മാറ്റപ്പെടാതിരിക്കുന്ന ഗുണം','വഞ്ചനാ സന്ദേശം: വിശ്വസനീയ ഉറവിടമെന്ന വ്യാജേന ഉപയോക്താവിനെ തെറ്റിദ്ധരിപ്പിക്കുന്ന സന്ദേശം'],'വിവര സുരക്ഷ; രഹസ്യത','വിവര സുരക്ഷ: വിവരങ്ങളുടെ രഹസ്യത സമഗ്രത ലഭ്യത എന്നിവ സംരക്ഷിക്കുന്ന ശാസ്ത്രശാഖ. രഹസ്യത: അനുമതിയുള്ള വ്യക്തികൾക്ക് മാത്രം വിവരങ്ങൾ ലഭ്യമാകുന്ന ഗുണം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Multiple Choice','Medium',2,'താഴെപ്പറയുന്നവയിൽ രഹസ്യതയും സമഗ്രതയും സംബന്ധിച്ച് ശരിയായ പ്രസ്താവനകൾ തിരഞ്ഞെടുക്കുക.',ARRAY['രഹസ്യത: അനുമതിയുള്ള വ്യക്തികൾക്ക് മാത്രം വിവരങ്ങൾ ലഭ്യമാകുന്ന ഗുണം','സമഗ്രത: വിവരങ്ങൾ അനധികൃതമായി മാറ്റപ്പെടാതിരിക്കുന്ന ഗുണം','ലഭ്യത: അധികാരമുള്ള ഉപയോക്താക്കൾക്ക് ആവശ്യസമയത്ത് വിഭവം ലഭിക്കുന്ന ഗുണം','സാമൂഹിക എഞ്ചിനീയറിംഗ്: മനുഷ്യരുടെ വിശ്വാസവും പെരുമാറ്റവും ചൂഷണം ചെയ്ത് വിവരങ്ങൾ നേടുന്ന രീതി'],'രഹസ്യത; സമഗ്രത','രഹസ്യത: അനുമതിയുള്ള വ്യക്തികൾക്ക് മാത്രം വിവരങ്ങൾ ലഭ്യമാകുന്ന ഗുണം. സമഗ്രത: വിവരങ്ങൾ അനധികൃതമായി മാറ്റപ്പെടാതിരിക്കുന്ന ഗുണം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Multiple Choice','Medium',2,'താഴെപ്പറയുന്നവയിൽ സമഗ്രതയും ലഭ്യതയും സംബന്ധിച്ച് ശരിയായ പ്രസ്താവനകൾ തിരഞ്ഞെടുക്കുക.',ARRAY['സമഗ്രത: വിവരങ്ങൾ അനധികൃതമായി മാറ്റപ്പെടാതിരിക്കുന്ന ഗുണം','ലഭ്യത: അധികാരമുള്ള ഉപയോക്താക്കൾക്ക് ആവശ്യസമയത്ത് വിഭവം ലഭിക്കുന്ന ഗുണം','ക്ഷുദ്ര സോഫ്റ്റ്‌വെയർ: കമ്പ്യൂട്ടർ സംവിധാനത്തിന് ദോഷം ചെയ്യാനോ അനധികൃത പ്രവർത്തനം നടത്താനോ രൂപകൽപ്പന ചെയ്ത സോഫ്റ്റ്‌വെയർ','പാസ്‌വേഡ് ആക്രമണം: പാസ്‌വേഡ് കണ്ടെത്താനോ മറികടക്കാനോ നടത്തുന്ന ആക്രമണം'],'സമഗ്രത; ലഭ്യത','സമഗ്രത: വിവരങ്ങൾ അനധികൃതമായി മാറ്റപ്പെടാതിരിക്കുന്ന ഗുണം. ലഭ്യത: അധികാരമുള്ള ഉപയോക്താക്കൾക്ക് ആവശ്യസമയത്ത് വിഭവം ലഭിക്കുന്ന ഗുണം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Multiple Choice','Medium',2,'താഴെപ്പറയുന്നവയിൽ ലഭ്യതയും ക്ഷുദ്ര സോഫ്റ്റ്‌വെയർയും സംബന്ധിച്ച് ശരിയായ പ്രസ്താവനകൾ തിരഞ്ഞെടുക്കുക.',ARRAY['ലഭ്യത: അധികാരമുള്ള ഉപയോക്താക്കൾക്ക് ആവശ്യസമയത്ത് വിഭവം ലഭിക്കുന്ന ഗുണം','ക്ഷുദ്ര സോഫ്റ്റ്‌വെയർ: കമ്പ്യൂട്ടർ സംവിധാനത്തിന് ദോഷം ചെയ്യാനോ അനധികൃത പ്രവർത്തനം നടത്താനോ രൂപകൽപ്പന ചെയ്ത സോഫ്റ്റ്‌വെയർ','വൈറസ്: മറ്റൊരു പ്രോഗ്രാമിൽ ചേർന്ന് വ്യാപിക്കുന്ന ക്ഷുദ്ര പ്രോഗ്രാം','ബ്രൂട്ട് ഫോഴ്‌സ് ആക്രമണം: സാധ്യമായ നിരവധി പാസ്‌വേഡുകൾ പരീക്ഷിക്കുന്ന ആക്രമണ രീതി'],'ലഭ്യത; ക്ഷുദ്ര സോഫ്റ്റ്‌വെയർ','ലഭ്യത: അധികാരമുള്ള ഉപയോക്താക്കൾക്ക് ആവശ്യസമയത്ത് വിഭവം ലഭിക്കുന്ന ഗുണം. ക്ഷുദ്ര സോഫ്റ്റ്‌വെയർ: കമ്പ്യൂട്ടർ സംവിധാനത്തിന് ദോഷം ചെയ്യാനോ അനധികൃത പ്രവർത്തനം നടത്താനോ രൂപകൽപ്പന ചെയ്ത സോഫ്റ്റ്‌വെയർ.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Multiple Choice','Medium',2,'താഴെപ്പറയുന്നവയിൽ ക്ഷുദ്ര സോഫ്റ്റ്‌വെയർയും വൈറസ്യും സംബന്ധിച്ച് ശരിയായ പ്രസ്താവനകൾ തിരഞ്ഞെടുക്കുക.',ARRAY['ക്ഷുദ്ര സോഫ്റ്റ്‌വെയർ: കമ്പ്യൂട്ടർ സംവിധാനത്തിന് ദോഷം ചെയ്യാനോ അനധികൃത പ്രവർത്തനം നടത്താനോ രൂപകൽപ്പന ചെയ്ത സോഫ്റ്റ്‌വെയർ','വൈറസ്: മറ്റൊരു പ്രോഗ്രാമിൽ ചേർന്ന് വ്യാപിക്കുന്ന ക്ഷുദ്ര പ്രോഗ്രാം','കൃമി: സ്വയം പകർത്തി ശൃംഖലകളിലൂടെ വ്യാപിക്കാൻ കഴിയുന്ന ക്ഷുദ്ര പ്രോഗ്രാം','ബഹുഘടക തിരിച്ചറിയൽ: ഒന്നിലധികം തിരിച്ചറിയൽ തെളിവുകൾ ഉപയോഗിക്കുന്ന സുരക്ഷാ രീതി'],'ക്ഷുദ്ര സോഫ്റ്റ്‌വെയർ; വൈറസ്','ക്ഷുദ്ര സോഫ്റ്റ്‌വെയർ: കമ്പ്യൂട്ടർ സംവിധാനത്തിന് ദോഷം ചെയ്യാനോ അനധികൃത പ്രവർത്തനം നടത്താനോ രൂപകൽപ്പന ചെയ്ത സോഫ്റ്റ്‌വെയർ. വൈറസ്: മറ്റൊരു പ്രോഗ്രാമിൽ ചേർന്ന് വ്യാപിക്കുന്ന ക്ഷുദ്ര പ്രോഗ്രാം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Multiple Choice','Medium',2,'താഴെപ്പറയുന്നവയിൽ വൈറസ്യും കൃമിയും സംബന്ധിച്ച് ശരിയായ പ്രസ്താവനകൾ തിരഞ്ഞെടുക്കുക.',ARRAY['വൈറസ്: മറ്റൊരു പ്രോഗ്രാമിൽ ചേർന്ന് വ്യാപിക്കുന്ന ക്ഷുദ്ര പ്രോഗ്രാം','കൃമി: സ്വയം പകർത്തി ശൃംഖലകളിലൂടെ വ്യാപിക്കാൻ കഴിയുന്ന ക്ഷുദ്ര പ്രോഗ്രാം','ട്രോജൻ: ഉപകാരപ്രദമായ പ്രോഗ്രാമെന്ന ഭാവത്തിൽ മറഞ്ഞിരിക്കുന്ന ക്ഷുദ്ര സോഫ്റ്റ്‌വെയർ','അനുമതി നിയന്ത്രണം: ഉപയോക്താക്കൾക്ക് അനുവദിച്ച പ്രവർത്തനങ്ങൾ മാത്രം നടത്താൻ സഹായിക്കുന്ന സംവിധാനം'],'വൈറസ്; കൃമി','വൈറസ്: മറ്റൊരു പ്രോഗ്രാമിൽ ചേർന്ന് വ്യാപിക്കുന്ന ക്ഷുദ്ര പ്രോഗ്രാം. കൃമി: സ്വയം പകർത്തി ശൃംഖലകളിലൂടെ വ്യാപിക്കാൻ കഴിയുന്ന ക്ഷുദ്ര പ്രോഗ്രാം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Multiple Choice','Medium',2,'താഴെപ്പറയുന്നവയിൽ കൃമിയും ട്രോജൻയും സംബന്ധിച്ച് ശരിയായ പ്രസ്താവനകൾ തിരഞ്ഞെടുക്കുക.',ARRAY['കൃമി: സ്വയം പകർത്തി ശൃംഖലകളിലൂടെ വ്യാപിക്കാൻ കഴിയുന്ന ക്ഷുദ്ര പ്രോഗ്രാം','ട്രോജൻ: ഉപകാരപ്രദമായ പ്രോഗ്രാമെന്ന ഭാവത്തിൽ മറഞ്ഞിരിക്കുന്ന ക്ഷുദ്ര സോഫ്റ്റ്‌വെയർ','റാൻസംവെയർ: ഡാറ്റ പൂട്ടിയ ശേഷം മോചനത്തുക ആവശ്യപ്പെടുന്ന ക്ഷുദ്ര സോഫ്റ്റ്‌വെയർ','തിരിച്ചറിയൽ പരിശോധന: ഉപയോക്താവിന്റെ തിരിച്ചറിയൽ ശരിയാണെന്ന് സ്ഥിരീകരിക്കുന്ന പ്രക്രിയ'],'കൃമി; ട്രോജൻ','കൃമി: സ്വയം പകർത്തി ശൃംഖലകളിലൂടെ വ്യാപിക്കാൻ കഴിയുന്ന ക്ഷുദ്ര പ്രോഗ്രാം. ട്രോജൻ: ഉപകാരപ്രദമായ പ്രോഗ്രാമെന്ന ഭാവത്തിൽ മറഞ്ഞിരിക്കുന്ന ക്ഷുദ്ര സോഫ്റ്റ്‌വെയർ.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Multiple Choice','Medium',2,'താഴെപ്പറയുന്നവയിൽ ട്രോജൻയും റാൻസംവെയർയും സംബന്ധിച്ച് ശരിയായ പ്രസ്താവനകൾ തിരഞ്ഞെടുക്കുക.',ARRAY['ട്രോജൻ: ഉപകാരപ്രദമായ പ്രോഗ്രാമെന്ന ഭാവത്തിൽ മറഞ്ഞിരിക്കുന്ന ക്ഷുദ്ര സോഫ്റ്റ്‌വെയർ','റാൻസംവെയർ: ഡാറ്റ പൂട്ടിയ ശേഷം മോചനത്തുക ആവശ്യപ്പെടുന്ന ക്ഷുദ്ര സോഫ്റ്റ്‌വെയർ','ചാര സോഫ്റ്റ്‌വെയർ: ഉപയോക്താവിന്റെ പ്രവർത്തനങ്ങൾ രഹസ്യമായി നിരീക്ഷിക്കുന്ന ക്ഷുദ്ര സോഫ്റ്റ്‌വെയർ','അഗ്നിരോധ മതിൽ: അനുവദിക്കാത്ത ശൃംഖലാ ബന്ധങ്ങൾ തടയുന്ന സുരക്ഷാ സംവിധാനം'],'ട്രോജൻ; റാൻസംവെയർ','ട്രോജൻ: ഉപകാരപ്രദമായ പ്രോഗ്രാമെന്ന ഭാവത്തിൽ മറഞ്ഞിരിക്കുന്ന ക്ഷുദ്ര സോഫ്റ്റ്‌വെയർ. റാൻസംവെയർ: ഡാറ്റ പൂട്ടിയ ശേഷം മോചനത്തുക ആവശ്യപ്പെടുന്ന ക്ഷുദ്ര സോഫ്റ്റ്‌വെയർ.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Multiple Choice','Medium',2,'താഴെപ്പറയുന്നവയിൽ റാൻസംവെയർയും ചാര സോഫ്റ്റ്‌വെയർയും സംബന്ധിച്ച് ശരിയായ പ്രസ്താവനകൾ തിരഞ്ഞെടുക്കുക.',ARRAY['റാൻസംവെയർ: ഡാറ്റ പൂട്ടിയ ശേഷം മോചനത്തുക ആവശ്യപ്പെടുന്ന ക്ഷുദ്ര സോഫ്റ്റ്‌വെയർ','ചാര സോഫ്റ്റ്‌വെയർ: ഉപയോക്താവിന്റെ പ്രവർത്തനങ്ങൾ രഹസ്യമായി നിരീക്ഷിക്കുന്ന ക്ഷുദ്ര സോഫ്റ്റ്‌വെയർ','ഫിഷിംഗ്: വ്യാജ സന്ദേശങ്ങളിലൂടെ രഹസ്യ വിവരങ്ങൾ നേടാനുള്ള തട്ടിപ്പ് രീതി','ആക്രമണ കണ്ടെത്തൽ: സംശയാസ്പദമായ ശൃംഖലാ പ്രവർത്തനങ്ങൾ കണ്ടെത്തുന്ന സംവിധാനം'],'റാൻസംവെയർ; ചാര സോഫ്റ്റ്‌വെയർ','റാൻസംവെയർ: ഡാറ്റ പൂട്ടിയ ശേഷം മോചനത്തുക ആവശ്യപ്പെടുന്ന ക്ഷുദ്ര സോഫ്റ്റ്‌വെയർ. ചാര സോഫ്റ്റ്‌വെയർ: ഉപയോക്താവിന്റെ പ്രവർത്തനങ്ങൾ രഹസ്യമായി നിരീക്ഷിക്കുന്ന ക്ഷുദ്ര സോഫ്റ്റ്‌വെയർ.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Multiple Choice','Medium',2,'താഴെപ്പറയുന്നവയിൽ ചാര സോഫ്റ്റ്‌വെയർയും ഫിഷിംഗ്യും സംബന്ധിച്ച് ശരിയായ പ്രസ്താവനകൾ തിരഞ്ഞെടുക്കുക.',ARRAY['ചാര സോഫ്റ്റ്‌വെയർ: ഉപയോക്താവിന്റെ പ്രവർത്തനങ്ങൾ രഹസ്യമായി നിരീക്ഷിക്കുന്ന ക്ഷുദ്ര സോഫ്റ്റ്‌വെയർ','ഫിഷിംഗ്: വ്യാജ സന്ദേശങ്ങളിലൂടെ രഹസ്യ വിവരങ്ങൾ നേടാനുള്ള തട്ടിപ്പ് രീതി','വഞ്ചനാ സന്ദേശം: വിശ്വസനീയ ഉറവിടമെന്ന വ്യാജേന ഉപയോക്താവിനെ തെറ്റിദ്ധരിപ്പിക്കുന്ന സന്ദേശം','ആക്രമണ തടയൽ: സംശയാസ്പദമായ പ്രവർത്തനങ്ങൾ കണ്ടെത്തുകയും തടയുകയും ചെയ്യുന്ന സംവിധാനം'],'ചാര സോഫ്റ്റ്‌വെയർ; ഫിഷിംഗ്','ചാര സോഫ്റ്റ്‌വെയർ: ഉപയോക്താവിന്റെ പ്രവർത്തനങ്ങൾ രഹസ്യമായി നിരീക്ഷിക്കുന്ന ക്ഷുദ്ര സോഫ്റ്റ്‌വെയർ. ഫിഷിംഗ്: വ്യാജ സന്ദേശങ്ങളിലൂടെ രഹസ്യ വിവരങ്ങൾ നേടാനുള്ള തട്ടിപ്പ് രീതി.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Multiple Choice','Medium',2,'താഴെപ്പറയുന്നവയിൽ ഫിഷിംഗ്യും വഞ്ചനാ സന്ദേശംയും സംബന്ധിച്ച് ശരിയായ പ്രസ്താവനകൾ തിരഞ്ഞെടുക്കുക.',ARRAY['ഫിഷിംഗ്: വ്യാജ സന്ദേശങ്ങളിലൂടെ രഹസ്യ വിവരങ്ങൾ നേടാനുള്ള തട്ടിപ്പ് രീതി','വഞ്ചനാ സന്ദേശം: വിശ്വസനീയ ഉറവിടമെന്ന വ്യാജേന ഉപയോക്താവിനെ തെറ്റിദ്ധരിപ്പിക്കുന്ന സന്ദേശം','സാമൂഹിക എഞ്ചിനീയറിംഗ്: മനുഷ്യരുടെ വിശ്വാസവും പെരുമാറ്റവും ചൂഷണം ചെയ്ത് വിവരങ്ങൾ നേടുന്ന രീതി','വിപിഎൻ: സുരക്ഷിതമായ സ്വകാര്യ ബന്ധം സൃഷ്ടിക്കുന്ന ശൃംഖലാ സാങ്കേതികവിദ്യ'],'ഫിഷിംഗ്; വഞ്ചനാ സന്ദേശം','ഫിഷിംഗ്: വ്യാജ സന്ദേശങ്ങളിലൂടെ രഹസ്യ വിവരങ്ങൾ നേടാനുള്ള തട്ടിപ്പ് രീതി. വഞ്ചനാ സന്ദേശം: വിശ്വസനീയ ഉറവിടമെന്ന വ്യാജേന ഉപയോക്താവിനെ തെറ്റിദ്ധരിപ്പിക്കുന്ന സന്ദേശം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Multiple Choice','Medium',2,'താഴെപ്പറയുന്നവയിൽ വഞ്ചനാ സന്ദേശംയും സാമൂഹിക എഞ്ചിനീയറിംഗ്യും സംബന്ധിച്ച് ശരിയായ പ്രസ്താവനകൾ തിരഞ്ഞെടുക്കുക.',ARRAY['വഞ്ചനാ സന്ദേശം: വിശ്വസനീയ ഉറവിടമെന്ന വ്യാജേന ഉപയോക്താവിനെ തെറ്റിദ്ധരിപ്പിക്കുന്ന സന്ദേശം','സാമൂഹിക എഞ്ചിനീയറിംഗ്: മനുഷ്യരുടെ വിശ്വാസവും പെരുമാറ്റവും ചൂഷണം ചെയ്ത് വിവരങ്ങൾ നേടുന്ന രീതി','പാസ്‌വേഡ് ആക്രമണം: പാസ്‌വേഡ് കണ്ടെത്താനോ മറികടക്കാനോ നടത്തുന്ന ആക്രമണം','എൻക്രിപ്ഷൻ: വിവരങ്ങളെ സംരക്ഷിത രൂപത്തിലേക്ക് മാറ്റുന്ന പ്രക്രിയ'],'വഞ്ചനാ സന്ദേശം; സാമൂഹിക എഞ്ചിനീയറിംഗ്','വഞ്ചനാ സന്ദേശം: വിശ്വസനീയ ഉറവിടമെന്ന വ്യാജേന ഉപയോക്താവിനെ തെറ്റിദ്ധരിപ്പിക്കുന്ന സന്ദേശം. സാമൂഹിക എഞ്ചിനീയറിംഗ്: മനുഷ്യരുടെ വിശ്വാസവും പെരുമാറ്റവും ചൂഷണം ചെയ്ത് വിവരങ്ങൾ നേടുന്ന രീതി.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Multiple Choice','Medium',2,'താഴെപ്പറയുന്നവയിൽ സാമൂഹിക എഞ്ചിനീയറിംഗ്യും പാസ്‌വേഡ് ആക്രമണംയും സംബന്ധിച്ച് ശരിയായ പ്രസ്താവനകൾ തിരഞ്ഞെടുക്കുക.',ARRAY['സാമൂഹിക എഞ്ചിനീയറിംഗ്: മനുഷ്യരുടെ വിശ്വാസവും പെരുമാറ്റവും ചൂഷണം ചെയ്ത് വിവരങ്ങൾ നേടുന്ന രീതി','പാസ്‌വേഡ് ആക്രമണം: പാസ്‌വേഡ് കണ്ടെത്താനോ മറികടക്കാനോ നടത്തുന്ന ആക്രമണം','ബ്രൂട്ട് ഫോഴ്‌സ് ആക്രമണം: സാധ്യമായ നിരവധി പാസ്‌വേഡുകൾ പരീക്ഷിക്കുന്ന ആക്രമണ രീതി','ഡീക്രിപ്ഷൻ: സംരക്ഷിത രൂപത്തിലുള്ള വിവരങ്ങളെ വായിക്കാവുന്ന രൂപത്തിലേക്ക് മാറ്റുന്ന പ്രക്രിയ'],'സാമൂഹിക എഞ്ചിനീയറിംഗ്; പാസ്‌വേഡ് ആക്രമണം','സാമൂഹിക എഞ്ചിനീയറിംഗ്: മനുഷ്യരുടെ വിശ്വാസവും പെരുമാറ്റവും ചൂഷണം ചെയ്ത് വിവരങ്ങൾ നേടുന്ന രീതി. പാസ്‌വേഡ് ആക്രമണം: പാസ്‌വേഡ് കണ്ടെത്താനോ മറികടക്കാനോ നടത്തുന്ന ആക്രമണം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Multiple Choice','Medium',2,'താഴെപ്പറയുന്നവയിൽ പാസ്‌വേഡ് ആക്രമണംയും ബ്രൂട്ട് ഫോഴ്‌സ് ആക്രമണംയും സംബന്ധിച്ച് ശരിയായ പ്രസ്താവനകൾ തിരഞ്ഞെടുക്കുക.',ARRAY['പാസ്‌വേഡ് ആക്രമണം: പാസ്‌വേഡ് കണ്ടെത്താനോ മറികടക്കാനോ നടത്തുന്ന ആക്രമണം','ബ്രൂട്ട് ഫോഴ്‌സ് ആക്രമണം: സാധ്യമായ നിരവധി പാസ്‌വേഡുകൾ പരീക്ഷിക്കുന്ന ആക്രമണ രീതി','ബഹുഘടക തിരിച്ചറിയൽ: ഒന്നിലധികം തിരിച്ചറിയൽ തെളിവുകൾ ഉപയോഗിക്കുന്ന സുരക്ഷാ രീതി','ഹാഷിംഗ്: ഡാറ്റയ്ക്ക് നിശ്ചിത നീളത്തിലുള്ള പ്രതിനിധി മൂല്യം സൃഷ്ടിക്കുന്ന ഏകദിശാ രീതി'],'പാസ്‌വേഡ് ആക്രമണം; ബ്രൂട്ട് ഫോഴ്‌സ് ആക്രമണം','പാസ്‌വേഡ് ആക്രമണം: പാസ്‌വേഡ് കണ്ടെത്താനോ മറികടക്കാനോ നടത്തുന്ന ആക്രമണം. ബ്രൂട്ട് ഫോഴ്‌സ് ആക്രമണം: സാധ്യമായ നിരവധി പാസ്‌വേഡുകൾ പരീക്ഷിക്കുന്ന ആക്രമണ രീതി.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Multiple Choice','Medium',2,'താഴെപ്പറയുന്നവയിൽ ബ്രൂട്ട് ഫോഴ്‌സ് ആക്രമണംയും ബഹുഘടക തിരിച്ചറിയൽയും സംബന്ധിച്ച് ശരിയായ പ്രസ്താവനകൾ തിരഞ്ഞെടുക്കുക.',ARRAY['ബ്രൂട്ട് ഫോഴ്‌സ് ആക്രമണം: സാധ്യമായ നിരവധി പാസ്‌വേഡുകൾ പരീക്ഷിക്കുന്ന ആക്രമണ രീതി','ബഹുഘടക തിരിച്ചറിയൽ: ഒന്നിലധികം തിരിച്ചറിയൽ തെളിവുകൾ ഉപയോഗിക്കുന്ന സുരക്ഷാ രീതി','അനുമതി നിയന്ത്രണം: ഉപയോക്താക്കൾക്ക് അനുവദിച്ച പ്രവർത്തനങ്ങൾ മാത്രം നടത്താൻ സഹായിക്കുന്ന സംവിധാനം','ഡിജിറ്റൽ ഒപ്പ്: ഡിജിറ്റൽ രേഖയുടെ ഉറവിടവും സമഗ്രതയും പരിശോധിക്കാൻ ഉപയോഗിക്കുന്ന സുരക്ഷാ രീതി'],'ബ്രൂട്ട് ഫോഴ്‌സ് ആക്രമണം; ബഹുഘടക തിരിച്ചറിയൽ','ബ്രൂട്ട് ഫോഴ്‌സ് ആക്രമണം: സാധ്യമായ നിരവധി പാസ്‌വേഡുകൾ പരീക്ഷിക്കുന്ന ആക്രമണ രീതി. ബഹുഘടക തിരിച്ചറിയൽ: ഒന്നിലധികം തിരിച്ചറിയൽ തെളിവുകൾ ഉപയോഗിക്കുന്ന സുരക്ഷാ രീതി.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Multiple Choice','Medium',2,'താഴെപ്പറയുന്നവയിൽ ബഹുഘടക തിരിച്ചറിയൽയും അനുമതി നിയന്ത്രണംയും സംബന്ധിച്ച് ശരിയായ പ്രസ്താവനകൾ തിരഞ്ഞെടുക്കുക.',ARRAY['ബഹുഘടക തിരിച്ചറിയൽ: ഒന്നിലധികം തിരിച്ചറിയൽ തെളിവുകൾ ഉപയോഗിക്കുന്ന സുരക്ഷാ രീതി','അനുമതി നിയന്ത്രണം: ഉപയോക്താക്കൾക്ക് അനുവദിച്ച പ്രവർത്തനങ്ങൾ മാത്രം നടത്താൻ സഹായിക്കുന്ന സംവിധാനം','തിരിച്ചറിയൽ പരിശോധന: ഉപയോക്താവിന്റെ തിരിച്ചറിയൽ ശരിയാണെന്ന് സ്ഥിരീകരിക്കുന്ന പ്രക്രിയ','സർട്ടിഫിക്കറ്റ്: ഡിജിറ്റൽ തിരിച്ചറിയലുമായി ബന്ധപ്പെട്ട വിശ്വാസയോഗ്യമായ രേഖ'],'ബഹുഘടക തിരിച്ചറിയൽ; അനുമതി നിയന്ത്രണം','ബഹുഘടക തിരിച്ചറിയൽ: ഒന്നിലധികം തിരിച്ചറിയൽ തെളിവുകൾ ഉപയോഗിക്കുന്ന സുരക്ഷാ രീതി. അനുമതി നിയന്ത്രണം: ഉപയോക്താക്കൾക്ക് അനുവദിച്ച പ്രവർത്തനങ്ങൾ മാത്രം നടത്താൻ സഹായിക്കുന്ന സംവിധാനം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Multiple Choice','Medium',2,'താഴെപ്പറയുന്നവയിൽ അനുമതി നിയന്ത്രണംയും തിരിച്ചറിയൽ പരിശോധനയും സംബന്ധിച്ച് ശരിയായ പ്രസ്താവനകൾ തിരഞ്ഞെടുക്കുക.',ARRAY['അനുമതി നിയന്ത്രണം: ഉപയോക്താക്കൾക്ക് അനുവദിച്ച പ്രവർത്തനങ്ങൾ മാത്രം നടത്താൻ സഹായിക്കുന്ന സംവിധാനം','തിരിച്ചറിയൽ പരിശോധന: ഉപയോക്താവിന്റെ തിരിച്ചറിയൽ ശരിയാണെന്ന് സ്ഥിരീകരിക്കുന്ന പ്രക്രിയ','അഗ്നിരോധ മതിൽ: അനുവദിക്കാത്ത ശൃംഖലാ ബന്ധങ്ങൾ തടയുന്ന സുരക്ഷാ സംവിധാനം','സുരക്ഷാ ദൗർബല്യം: ഒരു സംവിധാനത്തെ ആക്രമണത്തിന് വിധേയമാക്കാവുന്ന ബലഹീനത'],'അനുമതി നിയന്ത്രണം; തിരിച്ചറിയൽ പരിശോധന','അനുമതി നിയന്ത്രണം: ഉപയോക്താക്കൾക്ക് അനുവദിച്ച പ്രവർത്തനങ്ങൾ മാത്രം നടത്താൻ സഹായിക്കുന്ന സംവിധാനം. തിരിച്ചറിയൽ പരിശോധന: ഉപയോക്താവിന്റെ തിരിച്ചറിയൽ ശരിയാണെന്ന് സ്ഥിരീകരിക്കുന്ന പ്രക്രിയ.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Multiple Choice','Medium',2,'താഴെപ്പറയുന്നവയിൽ തിരിച്ചറിയൽ പരിശോധനയും അഗ്നിരോധ മതിൽയും സംബന്ധിച്ച് ശരിയായ പ്രസ്താവനകൾ തിരഞ്ഞെടുക്കുക.',ARRAY['തിരിച്ചറിയൽ പരിശോധന: ഉപയോക്താവിന്റെ തിരിച്ചറിയൽ ശരിയാണെന്ന് സ്ഥിരീകരിക്കുന്ന പ്രക്രിയ','അഗ്നിരോധ മതിൽ: അനുവദിക്കാത്ത ശൃംഖലാ ബന്ധങ്ങൾ തടയുന്ന സുരക്ഷാ സംവിധാനം','ആക്രമണ കണ്ടെത്തൽ: സംശയാസ്പദമായ ശൃംഖലാ പ്രവർത്തനങ്ങൾ കണ്ടെത്തുന്ന സംവിധാനം','ഭീഷണി: സുരക്ഷയ്ക്ക് ദോഷം വരുത്താൻ സാധ്യതയുള്ള സാഹചര്യമോ പ്രവർത്തനമോ'],'തിരിച്ചറിയൽ പരിശോധന; അഗ്നിരോധ മതിൽ','തിരിച്ചറിയൽ പരിശോധന: ഉപയോക്താവിന്റെ തിരിച്ചറിയൽ ശരിയാണെന്ന് സ്ഥിരീകരിക്കുന്ന പ്രക്രിയ. അഗ്നിരോധ മതിൽ: അനുവദിക്കാത്ത ശൃംഖലാ ബന്ധങ്ങൾ തടയുന്ന സുരക്ഷാ സംവിധാനം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Multiple Choice','Medium',2,'താഴെപ്പറയുന്നവയിൽ അഗ്നിരോധ മതിൽയും ആക്രമണ കണ്ടെത്തൽയും സംബന്ധിച്ച് ശരിയായ പ്രസ്താവനകൾ തിരഞ്ഞെടുക്കുക.',ARRAY['അഗ്നിരോധ മതിൽ: അനുവദിക്കാത്ത ശൃംഖലാ ബന്ധങ്ങൾ തടയുന്ന സുരക്ഷാ സംവിധാനം','ആക്രമണ കണ്ടെത്തൽ: സംശയാസ്പദമായ ശൃംഖലാ പ്രവർത്തനങ്ങൾ കണ്ടെത്തുന്ന സംവിധാനം','ആക്രമണ തടയൽ: സംശയാസ്പദമായ പ്രവർത്തനങ്ങൾ കണ്ടെത്തുകയും തടയുകയും ചെയ്യുന്ന സംവിധാനം','അപകടസാധ്യത: ഒരു ഭീഷണി ദൗർബല്യം ഉപയോഗപ്പെടുത്തുന്നതിലൂടെ ഉണ്ടാകാവുന്ന നഷ്ടസാധ്യത'],'അഗ്നിരോധ മതിൽ; ആക്രമണ കണ്ടെത്തൽ','അഗ്നിരോധ മതിൽ: അനുവദിക്കാത്ത ശൃംഖലാ ബന്ധങ്ങൾ തടയുന്ന സുരക്ഷാ സംവിധാനം. ആക്രമണ കണ്ടെത്തൽ: സംശയാസ്പദമായ ശൃംഖലാ പ്രവർത്തനങ്ങൾ കണ്ടെത്തുന്ന സംവിധാനം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Multiple Choice','Medium',2,'താഴെപ്പറയുന്നവയിൽ ആക്രമണ കണ്ടെത്തൽയും ആക്രമണ തടയൽയും സംബന്ധിച്ച് ശരിയായ പ്രസ്താവനകൾ തിരഞ്ഞെടുക്കുക.',ARRAY['ആക്രമണ കണ്ടെത്തൽ: സംശയാസ്പദമായ ശൃംഖലാ പ്രവർത്തനങ്ങൾ കണ്ടെത്തുന്ന സംവിധാനം','ആക്രമണ തടയൽ: സംശയാസ്പദമായ പ്രവർത്തനങ്ങൾ കണ്ടെത്തുകയും തടയുകയും ചെയ്യുന്ന സംവിധാനം','വിപിഎൻ: സുരക്ഷിതമായ സ്വകാര്യ ബന്ധം സൃഷ്ടിക്കുന്ന ശൃംഖലാ സാങ്കേതികവിദ്യ','സുരക്ഷാ പരിശോധന: സംവിധാനത്തിലെ ദൗർബല്യങ്ങൾ കണ്ടെത്തുന്നതിനുള്ള ക്രമബദ്ധമായ പരിശോധന'],'ആക്രമണ കണ്ടെത്തൽ; ആക്രമണ തടയൽ','ആക്രമണ കണ്ടെത്തൽ: സംശയാസ്പദമായ ശൃംഖലാ പ്രവർത്തനങ്ങൾ കണ്ടെത്തുന്ന സംവിധാനം. ആക്രമണ തടയൽ: സംശയാസ്പദമായ പ്രവർത്തനങ്ങൾ കണ്ടെത്തുകയും തടയുകയും ചെയ്യുന്ന സംവിധാനം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Multiple Choice','Medium',2,'താഴെപ്പറയുന്നവയിൽ ആക്രമണ തടയൽയും വിപിഎൻയും സംബന്ധിച്ച് ശരിയായ പ്രസ്താവനകൾ തിരഞ്ഞെടുക്കുക.',ARRAY['ആക്രമണ തടയൽ: സംശയാസ്പദമായ പ്രവർത്തനങ്ങൾ കണ്ടെത്തുകയും തടയുകയും ചെയ്യുന്ന സംവിധാനം','വിപിഎൻ: സുരക്ഷിതമായ സ്വകാര്യ ബന്ധം സൃഷ്ടിക്കുന്ന ശൃംഖലാ സാങ്കേതികവിദ്യ','എൻക്രിപ്ഷൻ: വിവരങ്ങളെ സംരക്ഷിത രൂപത്തിലേക്ക് മാറ്റുന്ന പ്രക്രിയ','പ്രവേശന പരിശോധന: സുരക്ഷാ നിയന്ത്രണങ്ങളെ പരീക്ഷിക്കാൻ അനുമതിയോടെ നടത്തുന്ന ആക്രമണ മാതൃകാ പരിശോധന'],'ആക്രമണ തടയൽ; വിപിഎൻ','ആക്രമണ തടയൽ: സംശയാസ്പദമായ പ്രവർത്തനങ്ങൾ കണ്ടെത്തുകയും തടയുകയും ചെയ്യുന്ന സംവിധാനം. വിപിഎൻ: സുരക്ഷിതമായ സ്വകാര്യ ബന്ധം സൃഷ്ടിക്കുന്ന ശൃംഖലാ സാങ്കേതികവിദ്യ.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Multiple Choice','Medium',2,'താഴെപ്പറയുന്നവയിൽ വിപിഎൻയും എൻക്രിപ്ഷൻയും സംബന്ധിച്ച് ശരിയായ പ്രസ്താവനകൾ തിരഞ്ഞെടുക്കുക.',ARRAY['വിപിഎൻ: സുരക്ഷിതമായ സ്വകാര്യ ബന്ധം സൃഷ്ടിക്കുന്ന ശൃംഖലാ സാങ്കേതികവിദ്യ','എൻക്രിപ്ഷൻ: വിവരങ്ങളെ സംരക്ഷിത രൂപത്തിലേക്ക് മാറ്റുന്ന പ്രക്രിയ','ഡീക്രിപ്ഷൻ: സംരക്ഷിത രൂപത്തിലുള്ള വിവരങ്ങളെ വായിക്കാവുന്ന രൂപത്തിലേക്ക് മാറ്റുന്ന പ്രക്രിയ','ലോഗ് നിരീക്ഷണം: സംവിധാന പ്രവർത്തനങ്ങളുടെ രേഖകൾ പരിശോധിച്ച് അസാധാരണത കണ്ടെത്തുന്ന പ്രവർത്തനം'],'വിപിഎൻ; എൻക്രിപ്ഷൻ','വിപിഎൻ: സുരക്ഷിതമായ സ്വകാര്യ ബന്ധം സൃഷ്ടിക്കുന്ന ശൃംഖലാ സാങ്കേതികവിദ്യ. എൻക്രിപ്ഷൻ: വിവരങ്ങളെ സംരക്ഷിത രൂപത്തിലേക്ക് മാറ്റുന്ന പ്രക്രിയ.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Multiple Choice','Medium',2,'താഴെപ്പറയുന്നവയിൽ എൻക്രിപ്ഷൻയും ഡീക്രിപ്ഷൻയും സംബന്ധിച്ച് ശരിയായ പ്രസ്താവനകൾ തിരഞ്ഞെടുക്കുക.',ARRAY['എൻക്രിപ്ഷൻ: വിവരങ്ങളെ സംരക്ഷിത രൂപത്തിലേക്ക് മാറ്റുന്ന പ്രക്രിയ','ഡീക്രിപ്ഷൻ: സംരക്ഷിത രൂപത്തിലുള്ള വിവരങ്ങളെ വായിക്കാവുന്ന രൂപത്തിലേക്ക് മാറ്റുന്ന പ്രക്രിയ','ഹാഷിംഗ്: ഡാറ്റയ്ക്ക് നിശ്ചിത നീളത്തിലുള്ള പ്രതിനിധി മൂല്യം സൃഷ്ടിക്കുന്ന ഏകദിശാ രീതി','സംഭവ പ്രതികരണം: സുരക്ഷാ സംഭവത്തെ തിരിച്ചറിഞ്ഞ് നിയന്ത്രിക്കുകയും പരിഹരിക്കുകയും ചെയ്യുന്ന പ്രക്രിയ'],'എൻക്രിപ്ഷൻ; ഡീക്രിപ്ഷൻ','എൻക്രിപ്ഷൻ: വിവരങ്ങളെ സംരക്ഷിത രൂപത്തിലേക്ക് മാറ്റുന്ന പ്രക്രിയ. ഡീക്രിപ്ഷൻ: സംരക്ഷിത രൂപത്തിലുള്ള വിവരങ്ങളെ വായിക്കാവുന്ന രൂപത്തിലേക്ക് മാറ്റുന്ന പ്രക്രിയ.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Multiple Choice','Medium',2,'താഴെപ്പറയുന്നവയിൽ ഡീക്രിപ്ഷൻയും ഹാഷിംഗ്യും സംബന്ധിച്ച് ശരിയായ പ്രസ്താവനകൾ തിരഞ്ഞെടുക്കുക.',ARRAY['ഡീക്രിപ്ഷൻ: സംരക്ഷിത രൂപത്തിലുള്ള വിവരങ്ങളെ വായിക്കാവുന്ന രൂപത്തിലേക്ക് മാറ്റുന്ന പ്രക്രിയ','ഹാഷിംഗ്: ഡാറ്റയ്ക്ക് നിശ്ചിത നീളത്തിലുള്ള പ്രതിനിധി മൂല്യം സൃഷ്ടിക്കുന്ന ഏകദിശാ രീതി','ഡിജിറ്റൽ ഒപ്പ്: ഡിജിറ്റൽ രേഖയുടെ ഉറവിടവും സമഗ്രതയും പരിശോധിക്കാൻ ഉപയോഗിക്കുന്ന സുരക്ഷാ രീതി','ഡാറ്റ ചോർച്ച: അനുമതിയില്ലാത്ത വ്യക്തികൾക്ക് സംരക്ഷിത വിവരങ്ങൾ ലഭിക്കുന്ന സംഭവം'],'ഡീക്രിപ്ഷൻ; ഹാഷിംഗ്','ഡീക്രിപ്ഷൻ: സംരക്ഷിത രൂപത്തിലുള്ള വിവരങ്ങളെ വായിക്കാവുന്ന രൂപത്തിലേക്ക് മാറ്റുന്ന പ്രക്രിയ. ഹാഷിംഗ്: ഡാറ്റയ്ക്ക് നിശ്ചിത നീളത്തിലുള്ള പ്രതിനിധി മൂല്യം സൃഷ്ടിക്കുന്ന ഏകദിശാ രീതി.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Multiple Choice','Medium',2,'താഴെപ്പറയുന്നവയിൽ ഹാഷിംഗ്യും ഡിജിറ്റൽ ഒപ്പ്യും സംബന്ധിച്ച് ശരിയായ പ്രസ്താവനകൾ തിരഞ്ഞെടുക്കുക.',ARRAY['ഹാഷിംഗ്: ഡാറ്റയ്ക്ക് നിശ്ചിത നീളത്തിലുള്ള പ്രതിനിധി മൂല്യം സൃഷ്ടിക്കുന്ന ഏകദിശാ രീതി','ഡിജിറ്റൽ ഒപ്പ്: ഡിജിറ്റൽ രേഖയുടെ ഉറവിടവും സമഗ്രതയും പരിശോധിക്കാൻ ഉപയോഗിക്കുന്ന സുരക്ഷാ രീതി','സർട്ടിഫിക്കറ്റ്: ഡിജിറ്റൽ തിരിച്ചറിയലുമായി ബന്ധപ്പെട്ട വിശ്വാസയോഗ്യമായ രേഖ','ബാക്കപ്പ്: നഷ്ടപ്പെട്ട ഡാറ്റ വീണ്ടെടുക്കുന്നതിനായി സൂക്ഷിക്കുന്ന പകർപ്പ്'],'ഹാഷിംഗ്; ഡിജിറ്റൽ ഒപ്പ്','ഹാഷിംഗ്: ഡാറ്റയ്ക്ക് നിശ്ചിത നീളത്തിലുള്ള പ്രതിനിധി മൂല്യം സൃഷ്ടിക്കുന്ന ഏകദിശാ രീതി. ഡിജിറ്റൽ ഒപ്പ്: ഡിജിറ്റൽ രേഖയുടെ ഉറവിടവും സമഗ്രതയും പരിശോധിക്കാൻ ഉപയോഗിക്കുന്ന സുരക്ഷാ രീതി.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Multiple Choice','Medium',2,'താഴെപ്പറയുന്നവയിൽ ഡിജിറ്റൽ ഒപ്പ്യും സർട്ടിഫിക്കറ്റ്യും സംബന്ധിച്ച് ശരിയായ പ്രസ്താവനകൾ തിരഞ്ഞെടുക്കുക.',ARRAY['ഡിജിറ്റൽ ഒപ്പ്: ഡിജിറ്റൽ രേഖയുടെ ഉറവിടവും സമഗ്രതയും പരിശോധിക്കാൻ ഉപയോഗിക്കുന്ന സുരക്ഷാ രീതി','സർട്ടിഫിക്കറ്റ്: ഡിജിറ്റൽ തിരിച്ചറിയലുമായി ബന്ധപ്പെട്ട വിശ്വാസയോഗ്യമായ രേഖ','സുരക്ഷാ ദൗർബല്യം: ഒരു സംവിധാനത്തെ ആക്രമണത്തിന് വിധേയമാക്കാവുന്ന ബലഹീനത','ദുരന്ത വീണ്ടെടുക്കൽ: വലിയ സുരക്ഷാ സംഭവത്തിന് ശേഷം സംവിധാനങ്ങളെ പുനഃസ്ഥാപിക്കുന്ന പദ്ധതി'],'ഡിജിറ്റൽ ഒപ്പ്; സർട്ടിഫിക്കറ്റ്','ഡിജിറ്റൽ ഒപ്പ്: ഡിജിറ്റൽ രേഖയുടെ ഉറവിടവും സമഗ്രതയും പരിശോധിക്കാൻ ഉപയോഗിക്കുന്ന സുരക്ഷാ രീതി. സർട്ടിഫിക്കറ്റ്: ഡിജിറ്റൽ തിരിച്ചറിയലുമായി ബന്ധപ്പെട്ട വിശ്വാസയോഗ്യമായ രേഖ.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Multiple Choice','Medium',2,'താഴെപ്പറയുന്നവയിൽ സർട്ടിഫിക്കറ്റ്യും സുരക്ഷാ ദൗർബല്യംയും സംബന്ധിച്ച് ശരിയായ പ്രസ്താവനകൾ തിരഞ്ഞെടുക്കുക.',ARRAY['സർട്ടിഫിക്കറ്റ്: ഡിജിറ്റൽ തിരിച്ചറിയലുമായി ബന്ധപ്പെട്ട വിശ്വാസയോഗ്യമായ രേഖ','സുരക്ഷാ ദൗർബല്യം: ഒരു സംവിധാനത്തെ ആക്രമണത്തിന് വിധേയമാക്കാവുന്ന ബലഹീനത','ഭീഷണി: സുരക്ഷയ്ക്ക് ദോഷം വരുത്താൻ സാധ്യതയുള്ള സാഹചര്യമോ പ്രവർത്തനമോ','സുരക്ഷാ ബോധവൽക്കരണം: ഉപയോക്താക്കളെ സുരക്ഷിതമായ ഡിജിറ്റൽ പെരുമാറ്റത്തെക്കുറിച്ച് പരിശീലിപ്പിക്കുന്ന പ്രവർത്തനം'],'സർട്ടിഫിക്കറ്റ്; സുരക്ഷാ ദൗർബല്യം','സർട്ടിഫിക്കറ്റ്: ഡിജിറ്റൽ തിരിച്ചറിയലുമായി ബന്ധപ്പെട്ട വിശ്വാസയോഗ്യമായ രേഖ. സുരക്ഷാ ദൗർബല്യം: ഒരു സംവിധാനത്തെ ആക്രമണത്തിന് വിധേയമാക്കാവുന്ന ബലഹീനത.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Multiple Choice','Medium',2,'താഴെപ്പറയുന്നവയിൽ സുരക്ഷാ ദൗർബല്യംയും ഭീഷണിയും സംബന്ധിച്ച് ശരിയായ പ്രസ്താവനകൾ തിരഞ്ഞെടുക്കുക.',ARRAY['സുരക്ഷാ ദൗർബല്യം: ഒരു സംവിധാനത്തെ ആക്രമണത്തിന് വിധേയമാക്കാവുന്ന ബലഹീനത','ഭീഷണി: സുരക്ഷയ്ക്ക് ദോഷം വരുത്താൻ സാധ്യതയുള്ള സാഹചര്യമോ പ്രവർത്തനമോ','അപകടസാധ്യത: ഒരു ഭീഷണി ദൗർബല്യം ഉപയോഗപ്പെടുത്തുന്നതിലൂടെ ഉണ്ടാകാവുന്ന നഷ്ടസാധ്യത','സുരക്ഷാ നയം: ഒരു സ്ഥാപനത്തിന്റെ സുരക്ഷാ നിയമങ്ങളും ഉത്തരവാദിത്തങ്ങളും വ്യക്തമാക്കുന്ന രേഖ'],'സുരക്ഷാ ദൗർബല്യം; ഭീഷണി','സുരക്ഷാ ദൗർബല്യം: ഒരു സംവിധാനത്തെ ആക്രമണത്തിന് വിധേയമാക്കാവുന്ന ബലഹീനത. ഭീഷണി: സുരക്ഷയ്ക്ക് ദോഷം വരുത്താൻ സാധ്യതയുള്ള സാഹചര്യമോ പ്രവർത്തനമോ.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Multiple Choice','Medium',2,'താഴെപ്പറയുന്നവയിൽ ഭീഷണിയും അപകടസാധ്യതയും സംബന്ധിച്ച് ശരിയായ പ്രസ്താവനകൾ തിരഞ്ഞെടുക്കുക.',ARRAY['ഭീഷണി: സുരക്ഷയ്ക്ക് ദോഷം വരുത്താൻ സാധ്യതയുള്ള സാഹചര്യമോ പ്രവർത്തനമോ','അപകടസാധ്യത: ഒരു ഭീഷണി ദൗർബല്യം ഉപയോഗപ്പെടുത്തുന്നതിലൂടെ ഉണ്ടാകാവുന്ന നഷ്ടസാധ്യത','സുരക്ഷാ പരിശോധന: സംവിധാനത്തിലെ ദൗർബല്യങ്ങൾ കണ്ടെത്തുന്നതിനുള്ള ക്രമബദ്ധമായ പരിശോധന','സൈബർ സുരക്ഷ: കമ്പ്യൂട്ടർ സംവിധാനങ്ങളെയും ശൃംഖലകളെയും ഡിജിറ്റൽ ഭീഷണികളിൽ നിന്ന് സംരക്ഷിക്കുന്ന പ്രവർത്തനം'],'ഭീഷണി; അപകടസാധ്യത','ഭീഷണി: സുരക്ഷയ്ക്ക് ദോഷം വരുത്താൻ സാധ്യതയുള്ള സാഹചര്യമോ പ്രവർത്തനമോ. അപകടസാധ്യത: ഒരു ഭീഷണി ദൗർബല്യം ഉപയോഗപ്പെടുത്തുന്നതിലൂടെ ഉണ്ടാകാവുന്ന നഷ്ടസാധ്യത.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Multiple Choice','Medium',2,'താഴെപ്പറയുന്നവയിൽ അപകടസാധ്യതയും സുരക്ഷാ പരിശോധനയും സംബന്ധിച്ച് ശരിയായ പ്രസ്താവനകൾ തിരഞ്ഞെടുക്കുക.',ARRAY['അപകടസാധ്യത: ഒരു ഭീഷണി ദൗർബല്യം ഉപയോഗപ്പെടുത്തുന്നതിലൂടെ ഉണ്ടാകാവുന്ന നഷ്ടസാധ്യത','സുരക്ഷാ പരിശോധന: സംവിധാനത്തിലെ ദൗർബല്യങ്ങൾ കണ്ടെത്തുന്നതിനുള്ള ക്രമബദ്ധമായ പരിശോധന','പ്രവേശന പരിശോധന: സുരക്ഷാ നിയന്ത്രണങ്ങളെ പരീക്ഷിക്കാൻ അനുമതിയോടെ നടത്തുന്ന ആക്രമണ മാതൃകാ പരിശോധന','വിവര സുരക്ഷ: വിവരങ്ങളുടെ രഹസ്യത സമഗ്രത ലഭ്യത എന്നിവ സംരക്ഷിക്കുന്ന ശാസ്ത്രശാഖ'],'അപകടസാധ്യത; സുരക്ഷാ പരിശോധന','അപകടസാധ്യത: ഒരു ഭീഷണി ദൗർബല്യം ഉപയോഗപ്പെടുത്തുന്നതിലൂടെ ഉണ്ടാകാവുന്ന നഷ്ടസാധ്യത. സുരക്ഷാ പരിശോധന: സംവിധാനത്തിലെ ദൗർബല്യങ്ങൾ കണ്ടെത്തുന്നതിനുള്ള ക്രമബദ്ധമായ പരിശോധന.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Multiple Choice','Medium',2,'താഴെപ്പറയുന്നവയിൽ സുരക്ഷാ പരിശോധനയും പ്രവേശന പരിശോധനയും സംബന്ധിച്ച് ശരിയായ പ്രസ്താവനകൾ തിരഞ്ഞെടുക്കുക.',ARRAY['സുരക്ഷാ പരിശോധന: സംവിധാനത്തിലെ ദൗർബല്യങ്ങൾ കണ്ടെത്തുന്നതിനുള്ള ക്രമബദ്ധമായ പരിശോധന','പ്രവേശന പരിശോധന: സുരക്ഷാ നിയന്ത്രണങ്ങളെ പരീക്ഷിക്കാൻ അനുമതിയോടെ നടത്തുന്ന ആക്രമണ മാതൃകാ പരിശോധന','ലോഗ് നിരീക്ഷണം: സംവിധാന പ്രവർത്തനങ്ങളുടെ രേഖകൾ പരിശോധിച്ച് അസാധാരണത കണ്ടെത്തുന്ന പ്രവർത്തനം','രഹസ്യത: അനുമതിയുള്ള വ്യക്തികൾക്ക് മാത്രം വിവരങ്ങൾ ലഭ്യമാകുന്ന ഗുണം'],'സുരക്ഷാ പരിശോധന; പ്രവേശന പരിശോധന','സുരക്ഷാ പരിശോധന: സംവിധാനത്തിലെ ദൗർബല്യങ്ങൾ കണ്ടെത്തുന്നതിനുള്ള ക്രമബദ്ധമായ പരിശോധന. പ്രവേശന പരിശോധന: സുരക്ഷാ നിയന്ത്രണങ്ങളെ പരീക്ഷിക്കാൻ അനുമതിയോടെ നടത്തുന്ന ആക്രമണ മാതൃകാ പരിശോധന.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Multiple Choice','Medium',2,'താഴെപ്പറയുന്നവയിൽ പ്രവേശന പരിശോധനയും ലോഗ് നിരീക്ഷണംയും സംബന്ധിച്ച് ശരിയായ പ്രസ്താവനകൾ തിരഞ്ഞെടുക്കുക.',ARRAY['പ്രവേശന പരിശോധന: സുരക്ഷാ നിയന്ത്രണങ്ങളെ പരീക്ഷിക്കാൻ അനുമതിയോടെ നടത്തുന്ന ആക്രമണ മാതൃകാ പരിശോധന','ലോഗ് നിരീക്ഷണം: സംവിധാന പ്രവർത്തനങ്ങളുടെ രേഖകൾ പരിശോധിച്ച് അസാധാരണത കണ്ടെത്തുന്ന പ്രവർത്തനം','സംഭവ പ്രതികരണം: സുരക്ഷാ സംഭവത്തെ തിരിച്ചറിഞ്ഞ് നിയന്ത്രിക്കുകയും പരിഹരിക്കുകയും ചെയ്യുന്ന പ്രക്രിയ','സമഗ്രത: വിവരങ്ങൾ അനധികൃതമായി മാറ്റപ്പെടാതിരിക്കുന്ന ഗുണം'],'പ്രവേശന പരിശോധന; ലോഗ് നിരീക്ഷണം','പ്രവേശന പരിശോധന: സുരക്ഷാ നിയന്ത്രണങ്ങളെ പരീക്ഷിക്കാൻ അനുമതിയോടെ നടത്തുന്ന ആക്രമണ മാതൃകാ പരിശോധന. ലോഗ് നിരീക്ഷണം: സംവിധാന പ്രവർത്തനങ്ങളുടെ രേഖകൾ പരിശോധിച്ച് അസാധാരണത കണ്ടെത്തുന്ന പ്രവർത്തനം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Multiple Choice','Medium',2,'താഴെപ്പറയുന്നവയിൽ ലോഗ് നിരീക്ഷണംയും സംഭവ പ്രതികരണംയും സംബന്ധിച്ച് ശരിയായ പ്രസ്താവനകൾ തിരഞ്ഞെടുക്കുക.',ARRAY['ലോഗ് നിരീക്ഷണം: സംവിധാന പ്രവർത്തനങ്ങളുടെ രേഖകൾ പരിശോധിച്ച് അസാധാരണത കണ്ടെത്തുന്ന പ്രവർത്തനം','സംഭവ പ്രതികരണം: സുരക്ഷാ സംഭവത്തെ തിരിച്ചറിഞ്ഞ് നിയന്ത്രിക്കുകയും പരിഹരിക്കുകയും ചെയ്യുന്ന പ്രക്രിയ','ഡാറ്റ ചോർച്ച: അനുമതിയില്ലാത്ത വ്യക്തികൾക്ക് സംരക്ഷിത വിവരങ്ങൾ ലഭിക്കുന്ന സംഭവം','ലഭ്യത: അധികാരമുള്ള ഉപയോക്താക്കൾക്ക് ആവശ്യസമയത്ത് വിഭവം ലഭിക്കുന്ന ഗുണം'],'ലോഗ് നിരീക്ഷണം; സംഭവ പ്രതികരണം','ലോഗ് നിരീക്ഷണം: സംവിധാന പ്രവർത്തനങ്ങളുടെ രേഖകൾ പരിശോധിച്ച് അസാധാരണത കണ്ടെത്തുന്ന പ്രവർത്തനം. സംഭവ പ്രതികരണം: സുരക്ഷാ സംഭവത്തെ തിരിച്ചറിഞ്ഞ് നിയന്ത്രിക്കുകയും പരിഹരിക്കുകയും ചെയ്യുന്ന പ്രക്രിയ.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Multiple Choice','Medium',2,'താഴെപ്പറയുന്നവയിൽ സംഭവ പ്രതികരണംയും ഡാറ്റ ചോർച്ചയും സംബന്ധിച്ച് ശരിയായ പ്രസ്താവനകൾ തിരഞ്ഞെടുക്കുക.',ARRAY['സംഭവ പ്രതികരണം: സുരക്ഷാ സംഭവത്തെ തിരിച്ചറിഞ്ഞ് നിയന്ത്രിക്കുകയും പരിഹരിക്കുകയും ചെയ്യുന്ന പ്രക്രിയ','ഡാറ്റ ചോർച്ച: അനുമതിയില്ലാത്ത വ്യക്തികൾക്ക് സംരക്ഷിത വിവരങ്ങൾ ലഭിക്കുന്ന സംഭവം','ബാക്കപ്പ്: നഷ്ടപ്പെട്ട ഡാറ്റ വീണ്ടെടുക്കുന്നതിനായി സൂക്ഷിക്കുന്ന പകർപ്പ്','ക്ഷുദ്ര സോഫ്റ്റ്‌വെയർ: കമ്പ്യൂട്ടർ സംവിധാനത്തിന് ദോഷം ചെയ്യാനോ അനധികൃത പ്രവർത്തനം നടത്താനോ രൂപകൽപ്പന ചെയ്ത സോഫ്റ്റ്‌വെയർ'],'സംഭവ പ്രതികരണം; ഡാറ്റ ചോർച്ച','സംഭവ പ്രതികരണം: സുരക്ഷാ സംഭവത്തെ തിരിച്ചറിഞ്ഞ് നിയന്ത്രിക്കുകയും പരിഹരിക്കുകയും ചെയ്യുന്ന പ്രക്രിയ. ഡാറ്റ ചോർച്ച: അനുമതിയില്ലാത്ത വ്യക്തികൾക്ക് സംരക്ഷിത വിവരങ്ങൾ ലഭിക്കുന്ന സംഭവം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','True/False','Easy',1,'ക്ഷുദ്ര സോഫ്റ്റ്‌വെയർ എന്നത് കമ്പ്യൂട്ടർ സംവിധാനത്തിന് ദോഷം ചെയ്യാനോ അനധികൃത പ്രവർത്തനം നടത്താനോ രൂപകൽപ്പന ചെയ്ത സോഫ്റ്റ്‌വെയർ എന്ന ആശയത്തെയാണ് സൂചിപ്പിക്കുന്നത്.',ARRAY['ശരി','തെറ്റ്'],'ശരി','ഈ പ്രസ്താവന ശരിയാണ്. കമ്പ്യൂട്ടർ സംവിധാനത്തിന് ദോഷം ചെയ്യാനോ അനധികൃത പ്രവർത്തനം നടത്താനോ രൂപകൽപ്പന ചെയ്ത സോഫ്റ്റ്‌വെയർ.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','True/False','Easy',1,'വൈറസ് എന്നത് മറ്റൊരു പ്രോഗ്രാമിൽ ചേർന്ന് വ്യാപിക്കുന്ന ക്ഷുദ്ര പ്രോഗ്രാം എന്ന ആശയത്തെയാണ് സൂചിപ്പിക്കുന്നത്.',ARRAY['ശരി','തെറ്റ്'],'ശരി','ഈ പ്രസ്താവന ശരിയാണ്. മറ്റൊരു പ്രോഗ്രാമിൽ ചേർന്ന് വ്യാപിക്കുന്ന ക്ഷുദ്ര പ്രോഗ്രാം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','True/False','Easy',1,'കൃമി എന്നത് സ്വയം പകർത്തി ശൃംഖലകളിലൂടെ വ്യാപിക്കാൻ കഴിയുന്ന ക്ഷുദ്ര പ്രോഗ്രാം എന്ന ആശയത്തെയാണ് സൂചിപ്പിക്കുന്നത്.',ARRAY['ശരി','തെറ്റ്'],'ശരി','ഈ പ്രസ്താവന ശരിയാണ്. സ്വയം പകർത്തി ശൃംഖലകളിലൂടെ വ്യാപിക്കാൻ കഴിയുന്ന ക്ഷുദ്ര പ്രോഗ്രാം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','True/False','Easy',1,'ട്രോജൻ എന്നത് ഉപകാരപ്രദമായ പ്രോഗ്രാമെന്ന ഭാവത്തിൽ മറഞ്ഞിരിക്കുന്ന ക്ഷുദ്ര സോഫ്റ്റ്‌വെയർ എന്ന ആശയത്തെയാണ് സൂചിപ്പിക്കുന്നത്.',ARRAY['ശരി','തെറ്റ്'],'ശരി','ഈ പ്രസ്താവന ശരിയാണ്. ഉപകാരപ്രദമായ പ്രോഗ്രാമെന്ന ഭാവത്തിൽ മറഞ്ഞിരിക്കുന്ന ക്ഷുദ്ര സോഫ്റ്റ്‌വെയർ.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','True/False','Easy',1,'റാൻസംവെയർ എന്നത് ഡാറ്റ പൂട്ടിയ ശേഷം മോചനത്തുക ആവശ്യപ്പെടുന്ന ക്ഷുദ്ര സോഫ്റ്റ്‌വെയർ എന്ന ആശയത്തെയാണ് സൂചിപ്പിക്കുന്നത്.',ARRAY['ശരി','തെറ്റ്'],'ശരി','ഈ പ്രസ്താവന ശരിയാണ്. ഡാറ്റ പൂട്ടിയ ശേഷം മോചനത്തുക ആവശ്യപ്പെടുന്ന ക്ഷുദ്ര സോഫ്റ്റ്‌വെയർ.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','True/False','Easy',1,'ചാര സോഫ്റ്റ്‌വെയർ എന്നത് ഉപയോക്താവിന്റെ പ്രവർത്തനങ്ങൾ രഹസ്യമായി നിരീക്ഷിക്കുന്ന ക്ഷുദ്ര സോഫ്റ്റ്‌വെയർ എന്ന ആശയത്തെയാണ് സൂചിപ്പിക്കുന്നത്.',ARRAY['ശരി','തെറ്റ്'],'ശരി','ഈ പ്രസ്താവന ശരിയാണ്. ഉപയോക്താവിന്റെ പ്രവർത്തനങ്ങൾ രഹസ്യമായി നിരീക്ഷിക്കുന്ന ക്ഷുദ്ര സോഫ്റ്റ്‌വെയർ.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','True/False','Easy',1,'ഫിഷിംഗ് എന്നത് വ്യാജ സന്ദേശങ്ങളിലൂടെ രഹസ്യ വിവരങ്ങൾ നേടാനുള്ള തട്ടിപ്പ് രീതി എന്ന ആശയത്തെയാണ് സൂചിപ്പിക്കുന്നത്.',ARRAY['ശരി','തെറ്റ്'],'ശരി','ഈ പ്രസ്താവന ശരിയാണ്. വ്യാജ സന്ദേശങ്ങളിലൂടെ രഹസ്യ വിവരങ്ങൾ നേടാനുള്ള തട്ടിപ്പ് രീതി.');
