INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','True/False','Easy',1,'സാമൂഹിക എഞ്ചിനീയറിംഗ് എന്നത് മനുഷ്യരുടെ വിശ്വാസവും പെരുമാറ്റവും ചൂഷണം ചെയ്ത് വിവരങ്ങൾ നേടുന്ന രീതി എന്ന ആശയത്തെയാണ് സൂചിപ്പിക്കുന്നത്.',ARRAY['ശരി','തെറ്റ്'],'ശരി','ഈ പ്രസ്താവന ശരിയാണ്. മനുഷ്യരുടെ വിശ്വാസവും പെരുമാറ്റവും ചൂഷണം ചെയ്ത് വിവരങ്ങൾ നേടുന്ന രീതി.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','True/False','Easy',1,'പാസ്‌വേഡ് ആക്രമണം എന്നത് പാസ്‌വേഡ് കണ്ടെത്താനോ മറികടക്കാനോ നടത്തുന്ന ആക്രമണം എന്ന ആശയത്തെയാണ് സൂചിപ്പിക്കുന്നത്.',ARRAY['ശരി','തെറ്റ്'],'ശരി','ഈ പ്രസ്താവന ശരിയാണ്. പാസ്‌വേഡ് കണ്ടെത്താനോ മറികടക്കാനോ നടത്തുന്ന ആക്രമണം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','True/False','Easy',1,'ബ്രൂട്ട് ഫോഴ്‌സ് ആക്രമണം എന്നത് സാധ്യമായ നിരവധി പാസ്‌വേഡുകൾ പരീക്ഷിക്കുന്ന ആക്രമണ രീതി എന്ന ആശയത്തെയാണ് സൂചിപ്പിക്കുന്നത്.',ARRAY['ശരി','തെറ്റ്'],'ശരി','ഈ പ്രസ്താവന ശരിയാണ്. സാധ്യമായ നിരവധി പാസ്‌വേഡുകൾ പരീക്ഷിക്കുന്ന ആക്രമണ രീതി.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','True/False','Easy',1,'ബഹുഘടക തിരിച്ചറിയൽ എന്നത് ഒന്നിലധികം തിരിച്ചറിയൽ തെളിവുകൾ ഉപയോഗിക്കുന്ന സുരക്ഷാ രീതി എന്ന ആശയത്തെയാണ് സൂചിപ്പിക്കുന്നത്.',ARRAY['ശരി','തെറ്റ്'],'ശരി','ഈ പ്രസ്താവന ശരിയാണ്. ഒന്നിലധികം തിരിച്ചറിയൽ തെളിവുകൾ ഉപയോഗിക്കുന്ന സുരക്ഷാ രീതി.');
