INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','True/False','Easy',1,'തിരിച്ചറിയൽ പരിശോധന എന്നത് ഉപയോക്താവിന്റെ തിരിച്ചറിയൽ ശരിയാണെന്ന് സ്ഥിരീകരിക്കുന്ന പ്രക്രിയ എന്ന ആശയത്തെയാണ് സൂചിപ്പിക്കുന്നത്.',ARRAY['ശരി','തെറ്റ്'],'ശരി','ഈ പ്രസ്താവന ശരിയാണ്. ഉപയോക്താവിന്റെ തിരിച്ചറിയൽ ശരിയാണെന്ന് സ്ഥിരീകരിക്കുന്ന പ്രക്രിയ.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','True/False','Easy',1,'അഗ്നിരോധ മതിൽ എന്നത് അനുവദിക്കാത്ത ശൃംഖലാ ബന്ധങ്ങൾ തടയുന്ന സുരക്ഷാ സംവിധാനം എന്ന ആശയത്തെയാണ് സൂചിപ്പിക്കുന്നത്.',ARRAY['ശരി','തെറ്റ്'],'ശരി','ഈ പ്രസ്താവന ശരിയാണ്. അനുവദിക്കാത്ത ശൃംഖലാ ബന്ധങ്ങൾ തടയുന്ന സുരക്ഷാ സംവിധാനം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','True/False','Easy',1,'ആക്രമണ കണ്ടെത്തൽ എന്നത് സംശയാസ്പദമായ ശൃംഖലാ പ്രവർത്തനങ്ങൾ കണ്ടെത്തുന്ന സംവിധാനം എന്ന ആശയത്തെയാണ് സൂചിപ്പിക്കുന്നത്.',ARRAY['ശരി','തെറ്റ്'],'ശരി','ഈ പ്രസ്താവന ശരിയാണ്. സംശയാസ്പദമായ ശൃംഖലാ പ്രവർത്തനങ്ങൾ കണ്ടെത്തുന്ന സംവിധാനം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','True/False','Easy',1,'ആക്രമണ തടയൽ എന്നത് സംശയാസ്പദമായ പ്രവർത്തനങ്ങൾ കണ്ടെത്തുകയും തടയുകയും ചെയ്യുന്ന സംവിധാനം എന്ന ആശയത്തെയാണ് സൂചിപ്പിക്കുന്നത്.',ARRAY['ശരി','തെറ്റ്'],'ശരി','ഈ പ്രസ്താവന ശരിയാണ്. സംശയാസ്പദമായ പ്രവർത്തനങ്ങൾ കണ്ടെത്തുകയും തടയുകയും ചെയ്യുന്ന സംവിധാനം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','True/False','Easy',1,'വിപിഎൻ എന്നത് സുരക്ഷിതമായ സ്വകാര്യ ബന്ധം സൃഷ്ടിക്കുന്ന ശൃംഖലാ സാങ്കേതികവിദ്യ എന്ന ആശയത്തെയാണ് സൂചിപ്പിക്കുന്നത്.',ARRAY['ശരി','തെറ്റ്'],'ശരി','ഈ പ്രസ്താവന ശരിയാണ്. സുരക്ഷിതമായ സ്വകാര്യ ബന്ധം സൃഷ്ടിക്കുന്ന ശൃംഖലാ സാങ്കേതികവിദ്യ.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','True/False','Easy',1,'എൻക്രിപ്ഷൻ എന്നത് വിവരങ്ങളെ സംരക്ഷിത രൂപത്തിലേക്ക് മാറ്റുന്ന പ്രക്രിയ എന്ന ആശയത്തെയാണ് സൂചിപ്പിക്കുന്നത്.',ARRAY['ശരി','തെറ്റ്'],'ശരി','ഈ പ്രസ്താവന ശരിയാണ്. വിവരങ്ങളെ സംരക്ഷിത രൂപത്തിലേക്ക് മാറ്റുന്ന പ്രക്രിയ.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','True/False','Easy',1,'ഡീക്രിപ്ഷൻ എന്നത് സംരക്ഷിത രൂപത്തിലുള്ള വിവരങ്ങളെ വായിക്കാവുന്ന രൂപത്തിലേക്ക് മാറ്റുന്ന പ്രക്രിയ എന്ന ആശയത്തെയാണ് സൂചിപ്പിക്കുന്നത്.',ARRAY['ശരി','തെറ്റ്'],'ശരി','ഈ പ്രസ്താവന ശരിയാണ്. സംരക്ഷിത രൂപത്തിലുള്ള വിവരങ്ങളെ വായിക്കാവുന്ന രൂപത്തിലേക്ക് മാറ്റുന്ന പ്രക്രിയ.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','True/False','Easy',1,'ഹാഷിംഗ് എന്നത് ഡാറ്റയ്ക്ക് നിശ്ചിത നീളത്തിലുള്ള പ്രതിനിധി മൂല്യം സൃഷ്ടിക്കുന്ന ഏകദിശാ രീതി എന്ന ആശയത്തെയാണ് സൂചിപ്പിക്കുന്നത്.',ARRAY['ശരി','തെറ്റ്'],'ശരി','ഈ പ്രസ്താവന ശരിയാണ്. ഡാറ്റയ്ക്ക് നിശ്ചിത നീളത്തിലുള്ള പ്രതിനിധി മൂല്യം സൃഷ്ടിക്കുന്ന ഏകദിശാ രീതി.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','True/False','Easy',1,'ഡിജിറ്റൽ ഒപ്പ് എന്നത് ഡിജിറ്റൽ രേഖയുടെ ഉറവിടവും സമഗ്രതയും പരിശോധിക്കാൻ ഉപയോഗിക്കുന്ന സുരക്ഷാ രീതി എന്ന ആശയത്തെയാണ് സൂചിപ്പിക്കുന്നത്.',ARRAY['ശരി','തെറ്റ്'],'ശരി','ഈ പ്രസ്താവന ശരിയാണ്. ഡിജിറ്റൽ രേഖയുടെ ഉറവിടവും സമഗ്രതയും പരിശോധിക്കാൻ ഉപയോഗിക്കുന്ന സുരക്ഷാ രീതി.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','True/False','Easy',1,'സർട്ടിഫിക്കറ്റ് എന്നത് ഡിജിറ്റൽ തിരിച്ചറിയലുമായി ബന്ധപ്പെട്ട വിശ്വാസയോഗ്യമായ രേഖ എന്ന ആശയത്തെയാണ് സൂചിപ്പിക്കുന്നത്.',ARRAY['ശരി','തെറ്റ്'],'ശരി','ഈ പ്രസ്താവന ശരിയാണ്. ഡിജിറ്റൽ തിരിച്ചറിയലുമായി ബന്ധപ്പെട്ട വിശ്വാസയോഗ്യമായ രേഖ.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','True/False','Easy',1,'സുരക്ഷാ ദൗർബല്യം എന്നത് ഒരു സംവിധാനത്തെ ആക്രമണത്തിന് വിധേയമാക്കാവുന്ന ബലഹീനത എന്ന ആശയത്തെയാണ് സൂചിപ്പിക്കുന്നത്.',ARRAY['ശരി','തെറ്റ്'],'ശരി','ഈ പ്രസ്താവന ശരിയാണ്. ഒരു സംവിധാനത്തെ ആക്രമണത്തിന് വിധേയമാക്കാവുന്ന ബലഹീനത.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','True/False','Easy',1,'ഭീഷണി എന്നത് സുരക്ഷയ്ക്ക് ദോഷം വരുത്താൻ സാധ്യതയുള്ള സാഹചര്യമോ പ്രവർത്തനമോ എന്ന ആശയത്തെയാണ് സൂചിപ്പിക്കുന്നത്.',ARRAY['ശരി','തെറ്റ്'],'ശരി','ഈ പ്രസ്താവന ശരിയാണ്. സുരക്ഷയ്ക്ക് ദോഷം വരുത്താൻ സാധ്യതയുള്ള സാഹചര്യമോ പ്രവർത്തനമോ.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','True/False','Easy',1,'അപകടസാധ്യത എന്നത് ഒരു ഭീഷണി ദൗർബല്യം ഉപയോഗപ്പെടുത്തുന്നതിലൂടെ ഉണ്ടാകാവുന്ന നഷ്ടസാധ്യത എന്ന ആശയത്തെയാണ് സൂചിപ്പിക്കുന്നത്.',ARRAY['ശരി','തെറ്റ്'],'ശരി','ഈ പ്രസ്താവന ശരിയാണ്. ഒരു ഭീഷണി ദൗർബല്യം ഉപയോഗപ്പെടുത്തുന്നതിലൂടെ ഉണ്ടാകാവുന്ന നഷ്ടസാധ്യത.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','True/False','Easy',1,'സുരക്ഷാ പരിശോധന എന്നത് സംവിധാനത്തിലെ ദൗർബല്യങ്ങൾ കണ്ടെത്തുന്നതിനുള്ള ക്രമബദ്ധമായ പരിശോധന എന്ന ആശയത്തെയാണ് സൂചിപ്പിക്കുന്നത്.',ARRAY['ശരി','തെറ്റ്'],'ശരി','ഈ പ്രസ്താവന ശരിയാണ്. സംവിധാനത്തിലെ ദൗർബല്യങ്ങൾ കണ്ടെത്തുന്നതിനുള്ള ക്രമബദ്ധമായ പരിശോധന.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','True/False','Easy',1,'പ്രവേശന പരിശോധന എന്നത് സുരക്ഷാ നിയന്ത്രണങ്ങളെ പരീക്ഷിക്കാൻ അനുമതിയോടെ നടത്തുന്ന ആക്രമണ മാതൃകാ പരിശോധന എന്ന ആശയത്തെയാണ് സൂചിപ്പിക്കുന്നത്.',ARRAY['ശരി','തെറ്റ്'],'ശരി','ഈ പ്രസ്താവന ശരിയാണ്. സുരക്ഷാ നിയന്ത്രണങ്ങളെ പരീക്ഷിക്കാൻ അനുമതിയോടെ നടത്തുന്ന ആക്രമണ മാതൃകാ പരിശോധന.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','True/False','Easy',1,'ലോഗ് നിരീക്ഷണം എന്നത് സംവിധാന പ്രവർത്തനങ്ങളുടെ രേഖകൾ പരിശോധിച്ച് അസാധാരണത കണ്ടെത്തുന്ന പ്രവർത്തനം എന്ന ആശയത്തെയാണ് സൂചിപ്പിക്കുന്നത്.',ARRAY['ശരി','തെറ്റ്'],'ശരി','ഈ പ്രസ്താവന ശരിയാണ്. സംവിധാന പ്രവർത്തനങ്ങളുടെ രേഖകൾ പരിശോധിച്ച് അസാധാരണത കണ്ടെത്തുന്ന പ്രവർത്തനം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','True/False','Easy',1,'സംഭവ പ്രതികരണം എന്നത് സുരക്ഷാ സംഭവത്തെ തിരിച്ചറിഞ്ഞ് നിയന്ത്രിക്കുകയും പരിഹരിക്കുകയും ചെയ്യുന്ന പ്രക്രിയ എന്ന ആശയത്തെയാണ് സൂചിപ്പിക്കുന്നത്.',ARRAY['ശരി','തെറ്റ്'],'ശരി','ഈ പ്രസ്താവന ശരിയാണ്. സുരക്ഷാ സംഭവത്തെ തിരിച്ചറിഞ്ഞ് നിയന്ത്രിക്കുകയും പരിഹരിക്കുകയും ചെയ്യുന്ന പ്രക്രിയ.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','True/False','Easy',1,'ഡാറ്റ ചോർച്ച എന്നത് അനുമതിയില്ലാത്ത വ്യക്തികൾക്ക് സംരക്ഷിത വിവരങ്ങൾ ലഭിക്കുന്ന സംഭവം എന്ന ആശയത്തെയാണ് സൂചിപ്പിക്കുന്നത്.',ARRAY['ശരി','തെറ്റ്'],'ശരി','ഈ പ്രസ്താവന ശരിയാണ്. അനുമതിയില്ലാത്ത വ്യക്തികൾക്ക് സംരക്ഷിത വിവരങ്ങൾ ലഭിക്കുന്ന സംഭവം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','True/False','Easy',1,'ബാക്കപ്പ് എന്നത് നഷ്ടപ്പെട്ട ഡാറ്റ വീണ്ടെടുക്കുന്നതിനായി സൂക്ഷിക്കുന്ന പകർപ്പ് എന്ന ആശയത്തെയാണ് സൂചിപ്പിക്കുന്നത്.',ARRAY['ശരി','തെറ്റ്'],'ശരി','ഈ പ്രസ്താവന ശരിയാണ്. നഷ്ടപ്പെട്ട ഡാറ്റ വീണ്ടെടുക്കുന്നതിനായി സൂക്ഷിക്കുന്ന പകർപ്പ്.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','True/False','Easy',1,'ദുരന്ത വീണ്ടെടുക്കൽ എന്നത് വലിയ സുരക്ഷാ സംഭവത്തിന് ശേഷം സംവിധാനങ്ങളെ പുനഃസ്ഥാപിക്കുന്ന പദ്ധതി എന്ന ആശയത്തെയാണ് സൂചിപ്പിക്കുന്നത്.',ARRAY['ശരി','തെറ്റ്'],'ശരി','ഈ പ്രസ്താവന ശരിയാണ്. വലിയ സുരക്ഷാ സംഭവത്തിന് ശേഷം സംവിധാനങ്ങളെ പുനഃസ്ഥാപിക്കുന്ന പദ്ധതി.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','True/False','Easy',1,'സുരക്ഷാ ബോധവൽക്കരണം എന്നത് ഉപയോക്താക്കളെ സുരക്ഷിതമായ ഡിജിറ്റൽ പെരുമാറ്റത്തെക്കുറിച്ച് പരിശീലിപ്പിക്കുന്ന പ്രവർത്തനം എന്ന ആശയത്തെയാണ് സൂചിപ്പിക്കുന്നത്.',ARRAY['ശരി','തെറ്റ്'],'ശരി','ഈ പ്രസ്താവന ശരിയാണ്. ഉപയോക്താക്കളെ സുരക്ഷിതമായ ഡിജിറ്റൽ പെരുമാറ്റത്തെക്കുറിച്ച് പരിശീലിപ്പിക്കുന്ന പ്രവർത്തനം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','True/False','Easy',1,'സുരക്ഷാ നയം എന്നത് ഒരു സ്ഥാപനത്തിന്റെ സുരക്ഷാ നിയമങ്ങളും ഉത്തരവാദിത്തങ്ങളും വ്യക്തമാക്കുന്ന രേഖ എന്ന ആശയത്തെയാണ് സൂചിപ്പിക്കുന്നത്.',ARRAY['ശരി','തെറ്റ്'],'ശരി','ഈ പ്രസ്താവന ശരിയാണ്. ഒരു സ്ഥാപനത്തിന്റെ സുരക്ഷാ നിയമങ്ങളും ഉത്തരവാദിത്തങ്ങളും വ്യക്തമാക്കുന്ന രേഖ.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Fill in the Blanks','Easy',1,'ഉപയോക്താവിന്റെ പ്രവർത്തനങ്ങൾ രഹസ്യമായി നിരീക്ഷിക്കുന്ന ക്ഷുദ്ര സോഫ്റ്റ്‌വെയർ എന്ന ആശയത്തെ __________ എന്ന് വിളിക്കുന്നു.',ARRAY[]::text[],'ചാര സോഫ്റ്റ്‌വെയർ','ശരിയായ പദം ചാര സോഫ്റ്റ്‌വെയർ ആണ്.');
