INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Fill in the Blanks','Easy',1,'വിശ്വസനീയ ഉറവിടമെന്ന വ്യാജേന ഉപയോക്താവിനെ തെറ്റിദ്ധരിപ്പിക്കുന്ന സന്ദേശം എന്ന ആശയത്തെ __________ എന്ന് വിളിക്കുന്നു.',ARRAY[]::text[],'വഞ്ചനാ സന്ദേശം','ശരിയായ പദം വഞ്ചനാ സന്ദേശം ആണ്.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Fill in the Blanks','Easy',1,'മനുഷ്യരുടെ വിശ്വാസവും പെരുമാറ്റവും ചൂഷണം ചെയ്ത് വിവരങ്ങൾ നേടുന്ന രീതി എന്ന ആശയത്തെ __________ എന്ന് വിളിക്കുന്നു.',ARRAY[]::text[],'സാമൂഹിക എഞ്ചിനീയറിംഗ്','ശരിയായ പദം സാമൂഹിക എഞ്ചിനീയറിംഗ് ആണ്.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Fill in the Blanks','Easy',1,'പാസ്‌വേഡ് കണ്ടെത്താനോ മറികടക്കാനോ നടത്തുന്ന ആക്രമണം എന്ന ആശയത്തെ __________ എന്ന് വിളിക്കുന്നു.',ARRAY[]::text[],'പാസ്‌വേഡ് ആക്രമണം','ശരിയായ പദം പാസ്‌വേഡ് ആക്രമണം ആണ്.');
