INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Fill in the Blanks','Easy',1,'ഒരു ഭീഷണി ദൗർബല്യം ഉപയോഗപ്പെടുത്തുന്നതിലൂടെ ഉണ്ടാകാവുന്ന നഷ്ടസാധ്യത എന്ന ആശയത്തെ __________ എന്ന് വിളിക്കുന്നു.',ARRAY[]::text[],'അപകടസാധ്യത','ശരിയായ പദം അപകടസാധ്യത ആണ്.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Fill in the Blanks','Easy',1,'സംവിധാനത്തിലെ ദൗർബല്യങ്ങൾ കണ്ടെത്തുന്നതിനുള്ള ക്രമബദ്ധമായ പരിശോധന എന്ന ആശയത്തെ __________ എന്ന് വിളിക്കുന്നു.',ARRAY[]::text[],'സുരക്ഷാ പരിശോധന','ശരിയായ പദം സുരക്ഷാ പരിശോധന ആണ്.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Fill in the Blanks','Easy',1,'സുരക്ഷാ നിയന്ത്രണങ്ങളെ പരീക്ഷിക്കാൻ അനുമതിയോടെ നടത്തുന്ന ആക്രമണ മാതൃകാ പരിശോധന എന്ന ആശയത്തെ __________ എന്ന് വിളിക്കുന്നു.',ARRAY[]::text[],'പ്രവേശന പരിശോധന','ശരിയായ പദം പ്രവേശന പരിശോധന ആണ്.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Fill in the Blanks','Easy',1,'സംവിധാന പ്രവർത്തനങ്ങളുടെ രേഖകൾ പരിശോധിച്ച് അസാധാരണത കണ്ടെത്തുന്ന പ്രവർത്തനം എന്ന ആശയത്തെ __________ എന്ന് വിളിക്കുന്നു.',ARRAY[]::text[],'ലോഗ് നിരീക്ഷണം','ശരിയായ പദം ലോഗ് നിരീക്ഷണം ആണ്.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Fill in the Blanks','Easy',1,'സുരക്ഷാ സംഭവത്തെ തിരിച്ചറിഞ്ഞ് നിയന്ത്രിക്കുകയും പരിഹരിക്കുകയും ചെയ്യുന്ന പ്രക്രിയ എന്ന ആശയത്തെ __________ എന്ന് വിളിക്കുന്നു.',ARRAY[]::text[],'സംഭവ പ്രതികരണം','ശരിയായ പദം സംഭവ പ്രതികരണം ആണ്.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Fill in the Blanks','Easy',1,'അനുമതിയില്ലാത്ത വ്യക്തികൾക്ക് സംരക്ഷിത വിവരങ്ങൾ ലഭിക്കുന്ന സംഭവം എന്ന ആശയത്തെ __________ എന്ന് വിളിക്കുന്നു.',ARRAY[]::text[],'ഡാറ്റ ചോർച്ച','ശരിയായ പദം ഡാറ്റ ചോർച്ച ആണ്.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Fill in the Blanks','Easy',1,'നഷ്ടപ്പെട്ട ഡാറ്റ വീണ്ടെടുക്കുന്നതിനായി സൂക്ഷിക്കുന്ന പകർപ്പ് എന്ന ആശയത്തെ __________ എന്ന് വിളിക്കുന്നു.',ARRAY[]::text[],'ബാക്കപ്പ്','ശരിയായ പദം ബാക്കപ്പ് ആണ്.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Fill in the Blanks','Easy',1,'വലിയ സുരക്ഷാ സംഭവത്തിന് ശേഷം സംവിധാനങ്ങളെ പുനഃസ്ഥാപിക്കുന്ന പദ്ധതി എന്ന ആശയത്തെ __________ എന്ന് വിളിക്കുന്നു.',ARRAY[]::text[],'ദുരന്ത വീണ്ടെടുക്കൽ','ശരിയായ പദം ദുരന്ത വീണ്ടെടുക്കൽ ആണ്.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Fill in the Blanks','Easy',1,'ഉപയോക്താക്കളെ സുരക്ഷിതമായ ഡിജിറ്റൽ പെരുമാറ്റത്തെക്കുറിച്ച് പരിശീലിപ്പിക്കുന്ന പ്രവർത്തനം എന്ന ആശയത്തെ __________ എന്ന് വിളിക്കുന്നു.',ARRAY[]::text[],'സുരക്ഷാ ബോധവൽക്കരണം','ശരിയായ പദം സുരക്ഷാ ബോധവൽക്കരണം ആണ്.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Fill in the Blanks','Easy',1,'ഒരു സ്ഥാപനത്തിന്റെ സുരക്ഷാ നിയമങ്ങളും ഉത്തരവാദിത്തങ്ങളും വ്യക്തമാക്കുന്ന രേഖ എന്ന ആശയത്തെ __________ എന്ന് വിളിക്കുന്നു.',ARRAY[]::text[],'സുരക്ഷാ നയം','ശരിയായ പദം സുരക്ഷാ നയം ആണ്.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Short Answer','Medium',3,'സൈബർ സുരക്ഷ എന്താണ്? അതിന്റെ പ്രധാന ഉദ്ദേശ്യം ചുരുക്കമായി വിശദീകരിക്കുക.',ARRAY[]::text[],'കമ്പ്യൂട്ടർ സംവിധാനങ്ങളെയും ശൃംഖലകളെയും ഡിജിറ്റൽ ഭീഷണികളിൽ നിന്ന് സംരക്ഷിക്കുന്ന പ്രവർത്തനം','സൈബർ സുരക്ഷ: കമ്പ്യൂട്ടർ സംവിധാനങ്ങളെയും ശൃംഖലകളെയും ഡിജിറ്റൽ ഭീഷണികളിൽ നിന്ന് സംരക്ഷിക്കുന്ന പ്രവർത്തനം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Short Answer','Medium',3,'വിവര സുരക്ഷ എന്താണ്? അതിന്റെ പ്രധാന ഉദ്ദേശ്യം ചുരുക്കമായി വിശദീകരിക്കുക.',ARRAY[]::text[],'വിവരങ്ങളുടെ രഹസ്യത സമഗ്രത ലഭ്യത എന്നിവ സംരക്ഷിക്കുന്ന ശാസ്ത്രശാഖ','വിവര സുരക്ഷ: വിവരങ്ങളുടെ രഹസ്യത സമഗ്രത ലഭ്യത എന്നിവ സംരക്ഷിക്കുന്ന ശാസ്ത്രശാഖ.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Short Answer','Medium',3,'രഹസ്യത എന്താണ്? അതിന്റെ പ്രധാന ഉദ്ദേശ്യം ചുരുക്കമായി വിശദീകരിക്കുക.',ARRAY[]::text[],'അനുമതിയുള്ള വ്യക്തികൾക്ക് മാത്രം വിവരങ്ങൾ ലഭ്യമാകുന്ന ഗുണം','രഹസ്യത: അനുമതിയുള്ള വ്യക്തികൾക്ക് മാത്രം വിവരങ്ങൾ ലഭ്യമാകുന്ന ഗുണം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Short Answer','Medium',3,'സമഗ്രത എന്താണ്? അതിന്റെ പ്രധാന ഉദ്ദേശ്യം ചുരുക്കമായി വിശദീകരിക്കുക.',ARRAY[]::text[],'വിവരങ്ങൾ അനധികൃതമായി മാറ്റപ്പെടാതിരിക്കുന്ന ഗുണം','സമഗ്രത: വിവരങ്ങൾ അനധികൃതമായി മാറ്റപ്പെടാതിരിക്കുന്ന ഗുണം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Short Answer','Medium',3,'ലഭ്യത എന്താണ്? അതിന്റെ പ്രധാന ഉദ്ദേശ്യം ചുരുക്കമായി വിശദീകരിക്കുക.',ARRAY[]::text[],'അധികാരമുള്ള ഉപയോക്താക്കൾക്ക് ആവശ്യസമയത്ത് വിഭവം ലഭിക്കുന്ന ഗുണം','ലഭ്യത: അധികാരമുള്ള ഉപയോക്താക്കൾക്ക് ആവശ്യസമയത്ത് വിഭവം ലഭിക്കുന്ന ഗുണം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Short Answer','Medium',3,'ക്ഷുദ്ര സോഫ്റ്റ്‌വെയർ എന്താണ്? അതിന്റെ പ്രധാന ഉദ്ദേശ്യം ചുരുക്കമായി വിശദീകരിക്കുക.',ARRAY[]::text[],'കമ്പ്യൂട്ടർ സംവിധാനത്തിന് ദോഷം ചെയ്യാനോ അനധികൃത പ്രവർത്തനം നടത്താനോ രൂപകൽപ്പന ചെയ്ത സോഫ്റ്റ്‌വെയർ','ക്ഷുദ്ര സോഫ്റ്റ്‌വെയർ: കമ്പ്യൂട്ടർ സംവിധാനത്തിന് ദോഷം ചെയ്യാനോ അനധികൃത പ്രവർത്തനം നടത്താനോ രൂപകൽപ്പന ചെയ്ത സോഫ്റ്റ്‌വെയർ.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Short Answer','Medium',3,'വൈറസ് എന്താണ്? അതിന്റെ പ്രധാന ഉദ്ദേശ്യം ചുരുക്കമായി വിശദീകരിക്കുക.',ARRAY[]::text[],'മറ്റൊരു പ്രോഗ്രാമിൽ ചേർന്ന് വ്യാപിക്കുന്ന ക്ഷുദ്ര പ്രോഗ്രാം','വൈറസ്: മറ്റൊരു പ്രോഗ്രാമിൽ ചേർന്ന് വ്യാപിക്കുന്ന ക്ഷുദ്ര പ്രോഗ്രാം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Short Answer','Medium',3,'കൃമി എന്താണ്? അതിന്റെ പ്രധാന ഉദ്ദേശ്യം ചുരുക്കമായി വിശദീകരിക്കുക.',ARRAY[]::text[],'സ്വയം പകർത്തി ശൃംഖലകളിലൂടെ വ്യാപിക്കാൻ കഴിയുന്ന ക്ഷുദ്ര പ്രോഗ്രാം','കൃമി: സ്വയം പകർത്തി ശൃംഖലകളിലൂടെ വ്യാപിക്കാൻ കഴിയുന്ന ക്ഷുദ്ര പ്രോഗ്രാം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Short Answer','Medium',3,'ട്രോജൻ എന്താണ്? അതിന്റെ പ്രധാന ഉദ്ദേശ്യം ചുരുക്കമായി വിശദീകരിക്കുക.',ARRAY[]::text[],'ഉപകാരപ്രദമായ പ്രോഗ്രാമെന്ന ഭാവത്തിൽ മറഞ്ഞിരിക്കുന്ന ക്ഷുദ്ര സോഫ്റ്റ്‌വെയർ','ട്രോജൻ: ഉപകാരപ്രദമായ പ്രോഗ്രാമെന്ന ഭാവത്തിൽ മറഞ്ഞിരിക്കുന്ന ക്ഷുദ്ര സോഫ്റ്റ്‌വെയർ.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Short Answer','Medium',3,'റാൻസംവെയർ എന്താണ്? അതിന്റെ പ്രധാന ഉദ്ദേശ്യം ചുരുക്കമായി വിശദീകരിക്കുക.',ARRAY[]::text[],'ഡാറ്റ പൂട്ടിയ ശേഷം മോചനത്തുക ആവശ്യപ്പെടുന്ന ക്ഷുദ്ര സോഫ്റ്റ്‌വെയർ','റാൻസംവെയർ: ഡാറ്റ പൂട്ടിയ ശേഷം മോചനത്തുക ആവശ്യപ്പെടുന്ന ക്ഷുദ്ര സോഫ്റ്റ്‌വെയർ.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Short Answer','Medium',3,'ചാര സോഫ്റ്റ്‌വെയർ എന്താണ്? അതിന്റെ പ്രധാന ഉദ്ദേശ്യം ചുരുക്കമായി വിശദീകരിക്കുക.',ARRAY[]::text[],'ഉപയോക്താവിന്റെ പ്രവർത്തനങ്ങൾ രഹസ്യമായി നിരീക്ഷിക്കുന്ന ക്ഷുദ്ര സോഫ്റ്റ്‌വെയർ','ചാര സോഫ്റ്റ്‌വെയർ: ഉപയോക്താവിന്റെ പ്രവർത്തനങ്ങൾ രഹസ്യമായി നിരീക്ഷിക്കുന്ന ക്ഷുദ്ര സോഫ്റ്റ്‌വെയർ.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Short Answer','Medium',3,'ഫിഷിംഗ് എന്താണ്? അതിന്റെ പ്രധാന ഉദ്ദേശ്യം ചുരുക്കമായി വിശദീകരിക്കുക.',ARRAY[]::text[],'വ്യാജ സന്ദേശങ്ങളിലൂടെ രഹസ്യ വിവരങ്ങൾ നേടാനുള്ള തട്ടിപ്പ് രീതി','ഫിഷിംഗ്: വ്യാജ സന്ദേശങ്ങളിലൂടെ രഹസ്യ വിവരങ്ങൾ നേടാനുള്ള തട്ടിപ്പ് രീതി.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Short Answer','Medium',3,'വഞ്ചനാ സന്ദേശം എന്താണ്? അതിന്റെ പ്രധാന ഉദ്ദേശ്യം ചുരുക്കമായി വിശദീകരിക്കുക.',ARRAY[]::text[],'വിശ്വസനീയ ഉറവിടമെന്ന വ്യാജേന ഉപയോക്താവിനെ തെറ്റിദ്ധരിപ്പിക്കുന്ന സന്ദേശം','വഞ്ചനാ സന്ദേശം: വിശ്വസനീയ ഉറവിടമെന്ന വ്യാജേന ഉപയോക്താവിനെ തെറ്റിദ്ധരിപ്പിക്കുന്ന സന്ദേശം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Short Answer','Medium',3,'സാമൂഹിക എഞ്ചിനീയറിംഗ് എന്താണ്? അതിന്റെ പ്രധാന ഉദ്ദേശ്യം ചുരുക്കമായി വിശദീകരിക്കുക.',ARRAY[]::text[],'മനുഷ്യരുടെ വിശ്വാസവും പെരുമാറ്റവും ചൂഷണം ചെയ്ത് വിവരങ്ങൾ നേടുന്ന രീതി','സാമൂഹിക എഞ്ചിനീയറിംഗ്: മനുഷ്യരുടെ വിശ്വാസവും പെരുമാറ്റവും ചൂഷണം ചെയ്ത് വിവരങ്ങൾ നേടുന്ന രീതി.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Short Answer','Medium',3,'പാസ്‌വേഡ് ആക്രമണം എന്താണ്? അതിന്റെ പ്രധാന ഉദ്ദേശ്യം ചുരുക്കമായി വിശദീകരിക്കുക.',ARRAY[]::text[],'പാസ്‌വേഡ് കണ്ടെത്താനോ മറികടക്കാനോ നടത്തുന്ന ആക്രമണം','പാസ്‌വേഡ് ആക്രമണം: പാസ്‌വേഡ് കണ്ടെത്താനോ മറികടക്കാനോ നടത്തുന്ന ആക്രമണം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Short Answer','Medium',3,'ബ്രൂട്ട് ഫോഴ്‌സ് ആക്രമണം എന്താണ്? അതിന്റെ പ്രധാന ഉദ്ദേശ്യം ചുരുക്കമായി വിശദീകരിക്കുക.',ARRAY[]::text[],'സാധ്യമായ നിരവധി പാസ്‌വേഡുകൾ പരീക്ഷിക്കുന്ന ആക്രമണ രീതി','ബ്രൂട്ട് ഫോഴ്‌സ് ആക്രമണം: സാധ്യമായ നിരവധി പാസ്‌വേഡുകൾ പരീക്ഷിക്കുന്ന ആക്രമണ രീതി.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Short Answer','Medium',3,'ബഹുഘടക തിരിച്ചറിയൽ എന്താണ്? അതിന്റെ പ്രധാന ഉദ്ദേശ്യം ചുരുക്കമായി വിശദീകരിക്കുക.',ARRAY[]::text[],'ഒന്നിലധികം തിരിച്ചറിയൽ തെളിവുകൾ ഉപയോഗിക്കുന്ന സുരക്ഷാ രീതി','ബഹുഘടക തിരിച്ചറിയൽ: ഒന്നിലധികം തിരിച്ചറിയൽ തെളിവുകൾ ഉപയോഗിക്കുന്ന സുരക്ഷാ രീതി.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Short Answer','Medium',3,'അനുമതി നിയന്ത്രണം എന്താണ്? അതിന്റെ പ്രധാന ഉദ്ദേശ്യം ചുരുക്കമായി വിശദീകരിക്കുക.',ARRAY[]::text[],'ഉപയോക്താക്കൾക്ക് അനുവദിച്ച പ്രവർത്തനങ്ങൾ മാത്രം നടത്താൻ സഹായിക്കുന്ന സംവിധാനം','അനുമതി നിയന്ത്രണം: ഉപയോക്താക്കൾക്ക് അനുവദിച്ച പ്രവർത്തനങ്ങൾ മാത്രം നടത്താൻ സഹായിക്കുന്ന സംവിധാനം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Short Answer','Medium',3,'തിരിച്ചറിയൽ പരിശോധന എന്താണ്? അതിന്റെ പ്രധാന ഉദ്ദേശ്യം ചുരുക്കമായി വിശദീകരിക്കുക.',ARRAY[]::text[],'ഉപയോക്താവിന്റെ തിരിച്ചറിയൽ ശരിയാണെന്ന് സ്ഥിരീകരിക്കുന്ന പ്രക്രിയ','തിരിച്ചറിയൽ പരിശോധന: ഉപയോക്താവിന്റെ തിരിച്ചറിയൽ ശരിയാണെന്ന് സ്ഥിരീകരിക്കുന്ന പ്രക്രിയ.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Short Answer','Medium',3,'അഗ്നിരോധ മതിൽ എന്താണ്? അതിന്റെ പ്രധാന ഉദ്ദേശ്യം ചുരുക്കമായി വിശദീകരിക്കുക.',ARRAY[]::text[],'അനുവദിക്കാത്ത ശൃംഖലാ ബന്ധങ്ങൾ തടയുന്ന സുരക്ഷാ സംവിധാനം','അഗ്നിരോധ മതിൽ: അനുവദിക്കാത്ത ശൃംഖലാ ബന്ധങ്ങൾ തടയുന്ന സുരക്ഷാ സംവിധാനം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Short Answer','Medium',3,'ആക്രമണ കണ്ടെത്തൽ എന്താണ്? അതിന്റെ പ്രധാന ഉദ്ദേശ്യം ചുരുക്കമായി വിശദീകരിക്കുക.',ARRAY[]::text[],'സംശയാസ്പദമായ ശൃംഖലാ പ്രവർത്തനങ്ങൾ കണ്ടെത്തുന്ന സംവിധാനം','ആക്രമണ കണ്ടെത്തൽ: സംശയാസ്പദമായ ശൃംഖലാ പ്രവർത്തനങ്ങൾ കണ്ടെത്തുന്ന സംവിധാനം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Short Answer','Medium',3,'ആക്രമണ തടയൽ എന്താണ്? അതിന്റെ പ്രധാന ഉദ്ദേശ്യം ചുരുക്കമായി വിശദീകരിക്കുക.',ARRAY[]::text[],'സംശയാസ്പദമായ പ്രവർത്തനങ്ങൾ കണ്ടെത്തുകയും തടയുകയും ചെയ്യുന്ന സംവിധാനം','ആക്രമണ തടയൽ: സംശയാസ്പദമായ പ്രവർത്തനങ്ങൾ കണ്ടെത്തുകയും തടയുകയും ചെയ്യുന്ന സംവിധാനം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Short Answer','Medium',3,'വിപിഎൻ എന്താണ്? അതിന്റെ പ്രധാന ഉദ്ദേശ്യം ചുരുക്കമായി വിശദീകരിക്കുക.',ARRAY[]::text[],'സുരക്ഷിതമായ സ്വകാര്യ ബന്ധം സൃഷ്ടിക്കുന്ന ശൃംഖലാ സാങ്കേതികവിദ്യ','വിപിഎൻ: സുരക്ഷിതമായ സ്വകാര്യ ബന്ധം സൃഷ്ടിക്കുന്ന ശൃംഖലാ സാങ്കേതികവിദ്യ.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Short Answer','Medium',3,'എൻക്രിപ്ഷൻ എന്താണ്? അതിന്റെ പ്രധാന ഉദ്ദേശ്യം ചുരുക്കമായി വിശദീകരിക്കുക.',ARRAY[]::text[],'വിവരങ്ങളെ സംരക്ഷിത രൂപത്തിലേക്ക് മാറ്റുന്ന പ്രക്രിയ','എൻക്രിപ്ഷൻ: വിവരങ്ങളെ സംരക്ഷിത രൂപത്തിലേക്ക് മാറ്റുന്ന പ്രക്രിയ.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Short Answer','Medium',3,'ഡീക്രിപ്ഷൻ എന്താണ്? അതിന്റെ പ്രധാന ഉദ്ദേശ്യം ചുരുക്കമായി വിശദീകരിക്കുക.',ARRAY[]::text[],'സംരക്ഷിത രൂപത്തിലുള്ള വിവരങ്ങളെ വായിക്കാവുന്ന രൂപത്തിലേക്ക് മാറ്റുന്ന പ്രക്രിയ','ഡീക്രിപ്ഷൻ: സംരക്ഷിത രൂപത്തിലുള്ള വിവരങ്ങളെ വായിക്കാവുന്ന രൂപത്തിലേക്ക് മാറ്റുന്ന പ്രക്രിയ.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Short Answer','Medium',3,'ഹാഷിംഗ് എന്താണ്? അതിന്റെ പ്രധാന ഉദ്ദേശ്യം ചുരുക്കമായി വിശദീകരിക്കുക.',ARRAY[]::text[],'ഡാറ്റയ്ക്ക് നിശ്ചിത നീളത്തിലുള്ള പ്രതിനിധി മൂല്യം സൃഷ്ടിക്കുന്ന ഏകദിശാ രീതി','ഹാഷിംഗ്: ഡാറ്റയ്ക്ക് നിശ്ചിത നീളത്തിലുള്ള പ്രതിനിധി മൂല്യം സൃഷ്ടിക്കുന്ന ഏകദിശാ രീതി.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Short Answer','Medium',3,'ഡിജിറ്റൽ ഒപ്പ് എന്താണ്? അതിന്റെ പ്രധാന ഉദ്ദേശ്യം ചുരുക്കമായി വിശദീകരിക്കുക.',ARRAY[]::text[],'ഡിജിറ്റൽ രേഖയുടെ ഉറവിടവും സമഗ്രതയും പരിശോധിക്കാൻ ഉപയോഗിക്കുന്ന സുരക്ഷാ രീതി','ഡിജിറ്റൽ ഒപ്പ്: ഡിജിറ്റൽ രേഖയുടെ ഉറവിടവും സമഗ്രതയും പരിശോധിക്കാൻ ഉപയോഗിക്കുന്ന സുരക്ഷാ രീതി.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Short Answer','Medium',3,'സർട്ടിഫിക്കറ്റ് എന്താണ്? അതിന്റെ പ്രധാന ഉദ്ദേശ്യം ചുരുക്കമായി വിശദീകരിക്കുക.',ARRAY[]::text[],'ഡിജിറ്റൽ തിരിച്ചറിയലുമായി ബന്ധപ്പെട്ട വിശ്വാസയോഗ്യമായ രേഖ','സർട്ടിഫിക്കറ്റ്: ഡിജിറ്റൽ തിരിച്ചറിയലുമായി ബന്ധപ്പെട്ട വിശ്വാസയോഗ്യമായ രേഖ.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Short Answer','Medium',3,'സുരക്ഷാ ദൗർബല്യം എന്താണ്? അതിന്റെ പ്രധാന ഉദ്ദേശ്യം ചുരുക്കമായി വിശദീകരിക്കുക.',ARRAY[]::text[],'ഒരു സംവിധാനത്തെ ആക്രമണത്തിന് വിധേയമാക്കാവുന്ന ബലഹീനത','സുരക്ഷാ ദൗർബല്യം: ഒരു സംവിധാനത്തെ ആക്രമണത്തിന് വിധേയമാക്കാവുന്ന ബലഹീനത.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Short Answer','Medium',3,'ഭീഷണി എന്താണ്? അതിന്റെ പ്രധാന ഉദ്ദേശ്യം ചുരുക്കമായി വിശദീകരിക്കുക.',ARRAY[]::text[],'സുരക്ഷയ്ക്ക് ദോഷം വരുത്താൻ സാധ്യതയുള്ള സാഹചര്യമോ പ്രവർത്തനമോ','ഭീഷണി: സുരക്ഷയ്ക്ക് ദോഷം വരുത്താൻ സാധ്യതയുള്ള സാഹചര്യമോ പ്രവർത്തനമോ.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Long Answer','Hard',5,'ചാര സോഫ്റ്റ്‌വെയർ വിശദമായി വിശദീകരിക്കുക. നിർവചനം പ്രവർത്തനരീതി പ്രധാന പ്രയോജനങ്ങൾ പരിമിതികൾ എന്നിവ ഉൾപ്പെടുത്തുക.',ARRAY[]::text[],'ചാര സോഫ്റ്റ്‌വെയർ എന്നത് ഉപയോക്താവിന്റെ പ്രവർത്തനങ്ങൾ രഹസ്യമായി നിരീക്ഷിക്കുന്ന ക്ഷുദ്ര സോഫ്റ്റ്‌വെയർ. ഇതിന്റെ പ്രധാന ലക്ഷ്യം ബന്ധപ്പെട്ട വിഭവങ്ങളെയോ വിവരങ്ങളെയോ കൂടുതൽ കാര്യക്ഷമമായും സുരക്ഷിതമായും കൈകാര്യം ചെയ്യുകയാണ്. ശരിയായ രൂപകൽപ്പന നിയന്ത്രണം നിരീക്ഷണം സുരക്ഷാ നടപടികൾ എന്നിവ ഉപയോഗിക്കുന്നത് ഇതിന്റെ പ്രയോജനം വർധിപ്പിക്കുന്നു.','ചാര സോഫ്റ്റ്‌വെയർ മനസ്സിലാക്കുമ്പോൾ അതിന്റെ നിർവചനം പ്രവർത്തനരീതി ഉപയോഗം ഗുണങ്ങൾ പരിമിതികൾ എന്നിവ പരിഗണിക്കണം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Long Answer','Hard',5,'ഫിഷിംഗ് വിശദമായി വിശദീകരിക്കുക. നിർവചനം പ്രവർത്തനരീതി പ്രധാന പ്രയോജനങ്ങൾ പരിമിതികൾ എന്നിവ ഉൾപ്പെടുത്തുക.',ARRAY[]::text[],'ഫിഷിംഗ് എന്നത് വ്യാജ സന്ദേശങ്ങളിലൂടെ രഹസ്യ വിവരങ്ങൾ നേടാനുള്ള തട്ടിപ്പ് രീതി. ഇതിന്റെ പ്രധാന ലക്ഷ്യം ബന്ധപ്പെട്ട വിഭവങ്ങളെയോ വിവരങ്ങളെയോ കൂടുതൽ കാര്യക്ഷമമായും സുരക്ഷിതമായും കൈകാര്യം ചെയ്യുകയാണ്. ശരിയായ രൂപകൽപ്പന നിയന്ത്രണം നിരീക്ഷണം സുരക്ഷാ നടപടികൾ എന്നിവ ഉപയോഗിക്കുന്നത് ഇതിന്റെ പ്രയോജനം വർധിപ്പിക്കുന്നു.','ഫിഷിംഗ് മനസ്സിലാക്കുമ്പോൾ അതിന്റെ നിർവചനം പ്രവർത്തനരീതി ഉപയോഗം ഗുണങ്ങൾ പരിമിതികൾ എന്നിവ പരിഗണിക്കണം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Long Answer','Hard',5,'വഞ്ചനാ സന്ദേശം വിശദമായി വിശദീകരിക്കുക. നിർവചനം പ്രവർത്തനരീതി പ്രധാന പ്രയോജനങ്ങൾ പരിമിതികൾ എന്നിവ ഉൾപ്പെടുത്തുക.',ARRAY[]::text[],'വഞ്ചനാ സന്ദേശം എന്നത് വിശ്വസനീയ ഉറവിടമെന്ന വ്യാജേന ഉപയോക്താവിനെ തെറ്റിദ്ധരിപ്പിക്കുന്ന സന്ദേശം. ഇതിന്റെ പ്രധാന ലക്ഷ്യം ബന്ധപ്പെട്ട വിഭവങ്ങളെയോ വിവരങ്ങളെയോ കൂടുതൽ കാര്യക്ഷമമായും സുരക്ഷിതമായും കൈകാര്യം ചെയ്യുകയാണ്. ശരിയായ രൂപകൽപ്പന നിയന്ത്രണം നിരീക്ഷണം സുരക്ഷാ നടപടികൾ എന്നിവ ഉപയോഗിക്കുന്നത് ഇതിന്റെ പ്രയോജനം വർധിപ്പിക്കുന്നു.','വഞ്ചനാ സന്ദേശം മനസ്സിലാക്കുമ്പോൾ അതിന്റെ നിർവചനം പ്രവർത്തനരീതി ഉപയോഗം ഗുണങ്ങൾ പരിമിതികൾ എന്നിവ പരിഗണിക്കണം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Long Answer','Hard',5,'സാമൂഹിക എഞ്ചിനീയറിംഗ് വിശദമായി വിശദീകരിക്കുക. നിർവചനം പ്രവർത്തനരീതി പ്രധാന പ്രയോജനങ്ങൾ പരിമിതികൾ എന്നിവ ഉൾപ്പെടുത്തുക.',ARRAY[]::text[],'സാമൂഹിക എഞ്ചിനീയറിംഗ് എന്നത് മനുഷ്യരുടെ വിശ്വാസവും പെരുമാറ്റവും ചൂഷണം ചെയ്ത് വിവരങ്ങൾ നേടുന്ന രീതി. ഇതിന്റെ പ്രധാന ലക്ഷ്യം ബന്ധപ്പെട്ട വിഭവങ്ങളെയോ വിവരങ്ങളെയോ കൂടുതൽ കാര്യക്ഷമമായും സുരക്ഷിതമായും കൈകാര്യം ചെയ്യുകയാണ്. ശരിയായ രൂപകൽപ്പന നിയന്ത്രണം നിരീക്ഷണം സുരക്ഷാ നടപടികൾ എന്നിവ ഉപയോഗിക്കുന്നത് ഇതിന്റെ പ്രയോജനം വർധിപ്പിക്കുന്നു.','സാമൂഹിക എഞ്ചിനീയറിംഗ് മനസ്സിലാക്കുമ്പോൾ അതിന്റെ നിർവചനം പ്രവർത്തനരീതി ഉപയോഗം ഗുണങ്ങൾ പരിമിതികൾ എന്നിവ പരിഗണിക്കണം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Long Answer','Hard',5,'പാസ്‌വേഡ് ആക്രമണം വിശദമായി വിശദീകരിക്കുക. നിർവചനം പ്രവർത്തനരീതി പ്രധാന പ്രയോജനങ്ങൾ പരിമിതികൾ എന്നിവ ഉൾപ്പെടുത്തുക.',ARRAY[]::text[],'പാസ്‌വേഡ് ആക്രമണം എന്നത് പാസ്‌വേഡ് കണ്ടെത്താനോ മറികടക്കാനോ നടത്തുന്ന ആക്രമണം. ഇതിന്റെ പ്രധാന ലക്ഷ്യം ബന്ധപ്പെട്ട വിഭവങ്ങളെയോ വിവരങ്ങളെയോ കൂടുതൽ കാര്യക്ഷമമായും സുരക്ഷിതമായും കൈകാര്യം ചെയ്യുകയാണ്. ശരിയായ രൂപകൽപ്പന നിയന്ത്രണം നിരീക്ഷണം സുരക്ഷാ നടപടികൾ എന്നിവ ഉപയോഗിക്കുന്നത് ഇതിന്റെ പ്രയോജനം വർധിപ്പിക്കുന്നു.','പാസ്‌വേഡ് ആക്രമണം മനസ്സിലാക്കുമ്പോൾ അതിന്റെ നിർവചനം പ്രവർത്തനരീതി ഉപയോഗം ഗുണങ്ങൾ പരിമിതികൾ എന്നിവ പരിഗണിക്കണം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Long Answer','Hard',5,'ബ്രൂട്ട് ഫോഴ്‌സ് ആക്രമണം വിശദമായി വിശദീകരിക്കുക. നിർവചനം പ്രവർത്തനരീതി പ്രധാന പ്രയോജനങ്ങൾ പരിമിതികൾ എന്നിവ ഉൾപ്പെടുത്തുക.',ARRAY[]::text[],'ബ്രൂട്ട് ഫോഴ്‌സ് ആക്രമണം എന്നത് സാധ്യമായ നിരവധി പാസ്‌വേഡുകൾ പരീക്ഷിക്കുന്ന ആക്രമണ രീതി. ഇതിന്റെ പ്രധാന ലക്ഷ്യം ബന്ധപ്പെട്ട വിഭവങ്ങളെയോ വിവരങ്ങളെയോ കൂടുതൽ കാര്യക്ഷമമായും സുരക്ഷിതമായും കൈകാര്യം ചെയ്യുകയാണ്. ശരിയായ രൂപകൽപ്പന നിയന്ത്രണം നിരീക്ഷണം സുരക്ഷാ നടപടികൾ എന്നിവ ഉപയോഗിക്കുന്നത് ഇതിന്റെ പ്രയോജനം വർധിപ്പിക്കുന്നു.','ബ്രൂട്ട് ഫോഴ്‌സ് ആക്രമണം മനസ്സിലാക്കുമ്പോൾ അതിന്റെ നിർവചനം പ്രവർത്തനരീതി ഉപയോഗം ഗുണങ്ങൾ പരിമിതികൾ എന്നിവ പരിഗണിക്കണം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Long Answer','Hard',5,'ബഹുഘടക തിരിച്ചറിയൽ വിശദമായി വിശദീകരിക്കുക. നിർവചനം പ്രവർത്തനരീതി പ്രധാന പ്രയോജനങ്ങൾ പരിമിതികൾ എന്നിവ ഉൾപ്പെടുത്തുക.',ARRAY[]::text[],'ബഹുഘടക തിരിച്ചറിയൽ എന്നത് ഒന്നിലധികം തിരിച്ചറിയൽ തെളിവുകൾ ഉപയോഗിക്കുന്ന സുരക്ഷാ രീതി. ഇതിന്റെ പ്രധാന ലക്ഷ്യം ബന്ധപ്പെട്ട വിഭവങ്ങളെയോ വിവരങ്ങളെയോ കൂടുതൽ കാര്യക്ഷമമായും സുരക്ഷിതമായും കൈകാര്യം ചെയ്യുകയാണ്. ശരിയായ രൂപകൽപ്പന നിയന്ത്രണം നിരീക്ഷണം സുരക്ഷാ നടപടികൾ എന്നിവ ഉപയോഗിക്കുന്നത് ഇതിന്റെ പ്രയോജനം വർധിപ്പിക്കുന്നു.','ബഹുഘടക തിരിച്ചറിയൽ മനസ്സിലാക്കുമ്പോൾ അതിന്റെ നിർവചനം പ്രവർത്തനരീതി ഉപയോഗം ഗുണങ്ങൾ പരിമിതികൾ എന്നിവ പരിഗണിക്കണം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Long Answer','Hard',5,'അനുമതി നിയന്ത്രണം വിശദമായി വിശദീകരിക്കുക. നിർവചനം പ്രവർത്തനരീതി പ്രധാന പ്രയോജനങ്ങൾ പരിമിതികൾ എന്നിവ ഉൾപ്പെടുത്തുക.',ARRAY[]::text[],'അനുമതി നിയന്ത്രണം എന്നത് ഉപയോക്താക്കൾക്ക് അനുവദിച്ച പ്രവർത്തനങ്ങൾ മാത്രം നടത്താൻ സഹായിക്കുന്ന സംവിധാനം. ഇതിന്റെ പ്രധാന ലക്ഷ്യം ബന്ധപ്പെട്ട വിഭവങ്ങളെയോ വിവരങ്ങളെയോ കൂടുതൽ കാര്യക്ഷമമായും സുരക്ഷിതമായും കൈകാര്യം ചെയ്യുകയാണ്. ശരിയായ രൂപകൽപ്പന നിയന്ത്രണം നിരീക്ഷണം സുരക്ഷാ നടപടികൾ എന്നിവ ഉപയോഗിക്കുന്നത് ഇതിന്റെ പ്രയോജനം വർധിപ്പിക്കുന്നു.','അനുമതി നിയന്ത്രണം മനസ്സിലാക്കുമ്പോൾ അതിന്റെ നിർവചനം പ്രവർത്തനരീതി ഉപയോഗം ഗുണങ്ങൾ പരിമിതികൾ എന്നിവ പരിഗണിക്കണം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Long Answer','Hard',5,'തിരിച്ചറിയൽ പരിശോധന വിശദമായി വിശദീകരിക്കുക. നിർവചനം പ്രവർത്തനരീതി പ്രധാന പ്രയോജനങ്ങൾ പരിമിതികൾ എന്നിവ ഉൾപ്പെടുത്തുക.',ARRAY[]::text[],'തിരിച്ചറിയൽ പരിശോധന എന്നത് ഉപയോക്താവിന്റെ തിരിച്ചറിയൽ ശരിയാണെന്ന് സ്ഥിരീകരിക്കുന്ന പ്രക്രിയ. ഇതിന്റെ പ്രധാന ലക്ഷ്യം ബന്ധപ്പെട്ട വിഭവങ്ങളെയോ വിവരങ്ങളെയോ കൂടുതൽ കാര്യക്ഷമമായും സുരക്ഷിതമായും കൈകാര്യം ചെയ്യുകയാണ്. ശരിയായ രൂപകൽപ്പന നിയന്ത്രണം നിരീക്ഷണം സുരക്ഷാ നടപടികൾ എന്നിവ ഉപയോഗിക്കുന്നത് ഇതിന്റെ പ്രയോജനം വർധിപ്പിക്കുന്നു.','തിരിച്ചറിയൽ പരിശോധന മനസ്സിലാക്കുമ്പോൾ അതിന്റെ നിർവചനം പ്രവർത്തനരീതി ഉപയോഗം ഗുണങ്ങൾ പരിമിതികൾ എന്നിവ പരിഗണിക്കണം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Long Answer','Hard',5,'അഗ്നിരോധ മതിൽ വിശദമായി വിശദീകരിക്കുക. നിർവചനം പ്രവർത്തനരീതി പ്രധാന പ്രയോജനങ്ങൾ പരിമിതികൾ എന്നിവ ഉൾപ്പെടുത്തുക.',ARRAY[]::text[],'അഗ്നിരോധ മതിൽ എന്നത് അനുവദിക്കാത്ത ശൃംഖലാ ബന്ധങ്ങൾ തടയുന്ന സുരക്ഷാ സംവിധാനം. ഇതിന്റെ പ്രധാന ലക്ഷ്യം ബന്ധപ്പെട്ട വിഭവങ്ങളെയോ വിവരങ്ങളെയോ കൂടുതൽ കാര്യക്ഷമമായും സുരക്ഷിതമായും കൈകാര്യം ചെയ്യുകയാണ്. ശരിയായ രൂപകൽപ്പന നിയന്ത്രണം നിരീക്ഷണം സുരക്ഷാ നടപടികൾ എന്നിവ ഉപയോഗിക്കുന്നത് ഇതിന്റെ പ്രയോജനം വർധിപ്പിക്കുന്നു.','അഗ്നിരോധ മതിൽ മനസ്സിലാക്കുമ്പോൾ അതിന്റെ നിർവചനം പ്രവർത്തനരീതി ഉപയോഗം ഗുണങ്ങൾ പരിമിതികൾ എന്നിവ പരിഗണിക്കണം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Long Answer','Hard',5,'ആക്രമണ കണ്ടെത്തൽ വിശദമായി വിശദീകരിക്കുക. നിർവചനം പ്രവർത്തനരീതി പ്രധാന പ്രയോജനങ്ങൾ പരിമിതികൾ എന്നിവ ഉൾപ്പെടുത്തുക.',ARRAY[]::text[],'ആക്രമണ കണ്ടെത്തൽ എന്നത് സംശയാസ്പദമായ ശൃംഖലാ പ്രവർത്തനങ്ങൾ കണ്ടെത്തുന്ന സംവിധാനം. ഇതിന്റെ പ്രധാന ലക്ഷ്യം ബന്ധപ്പെട്ട വിഭവങ്ങളെയോ വിവരങ്ങളെയോ കൂടുതൽ കാര്യക്ഷമമായും സുരക്ഷിതമായും കൈകാര്യം ചെയ്യുകയാണ്. ശരിയായ രൂപകൽപ്പന നിയന്ത്രണം നിരീക്ഷണം സുരക്ഷാ നടപടികൾ എന്നിവ ഉപയോഗിക്കുന്നത് ഇതിന്റെ പ്രയോജനം വർധിപ്പിക്കുന്നു.','ആക്രമണ കണ്ടെത്തൽ മനസ്സിലാക്കുമ്പോൾ അതിന്റെ നിർവചനം പ്രവർത്തനരീതി ഉപയോഗം ഗുണങ്ങൾ പരിമിതികൾ എന്നിവ പരിഗണിക്കണം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Long Answer','Hard',5,'ആക്രമണ തടയൽ വിശദമായി വിശദീകരിക്കുക. നിർവചനം പ്രവർത്തനരീതി പ്രധാന പ്രയോജനങ്ങൾ പരിമിതികൾ എന്നിവ ഉൾപ്പെടുത്തുക.',ARRAY[]::text[],'ആക്രമണ തടയൽ എന്നത് സംശയാസ്പദമായ പ്രവർത്തനങ്ങൾ കണ്ടെത്തുകയും തടയുകയും ചെയ്യുന്ന സംവിധാനം. ഇതിന്റെ പ്രധാന ലക്ഷ്യം ബന്ധപ്പെട്ട വിഭവങ്ങളെയോ വിവരങ്ങളെയോ കൂടുതൽ കാര്യക്ഷമമായും സുരക്ഷിതമായും കൈകാര്യം ചെയ്യുകയാണ്. ശരിയായ രൂപകൽപ്പന നിയന്ത്രണം നിരീക്ഷണം സുരക്ഷാ നടപടികൾ എന്നിവ ഉപയോഗിക്കുന്നത് ഇതിന്റെ പ്രയോജനം വർധിപ്പിക്കുന്നു.','ആക്രമണ തടയൽ മനസ്സിലാക്കുമ്പോൾ അതിന്റെ നിർവചനം പ്രവർത്തനരീതി ഉപയോഗം ഗുണങ്ങൾ പരിമിതികൾ എന്നിവ പരിഗണിക്കണം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Long Answer','Hard',5,'വിപിഎൻ വിശദമായി വിശദീകരിക്കുക. നിർവചനം പ്രവർത്തനരീതി പ്രധാന പ്രയോജനങ്ങൾ പരിമിതികൾ എന്നിവ ഉൾപ്പെടുത്തുക.',ARRAY[]::text[],'വിപിഎൻ എന്നത് സുരക്ഷിതമായ സ്വകാര്യ ബന്ധം സൃഷ്ടിക്കുന്ന ശൃംഖലാ സാങ്കേതികവിദ്യ. ഇതിന്റെ പ്രധാന ലക്ഷ്യം ബന്ധപ്പെട്ട വിഭവങ്ങളെയോ വിവരങ്ങളെയോ കൂടുതൽ കാര്യക്ഷമമായും സുരക്ഷിതമായും കൈകാര്യം ചെയ്യുകയാണ്. ശരിയായ രൂപകൽപ്പന നിയന്ത്രണം നിരീക്ഷണം സുരക്ഷാ നടപടികൾ എന്നിവ ഉപയോഗിക്കുന്നത് ഇതിന്റെ പ്രയോജനം വർധിപ്പിക്കുന്നു.','വിപിഎൻ മനസ്സിലാക്കുമ്പോൾ അതിന്റെ നിർവചനം പ്രവർത്തനരീതി ഉപയോഗം ഗുണങ്ങൾ പരിമിതികൾ എന്നിവ പരിഗണിക്കണം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Long Answer','Hard',5,'എൻക്രിപ്ഷൻ വിശദമായി വിശദീകരിക്കുക. നിർവചനം പ്രവർത്തനരീതി പ്രധാന പ്രയോജനങ്ങൾ പരിമിതികൾ എന്നിവ ഉൾപ്പെടുത്തുക.',ARRAY[]::text[],'എൻക്രിപ്ഷൻ എന്നത് വിവരങ്ങളെ സംരക്ഷിത രൂപത്തിലേക്ക് മാറ്റുന്ന പ്രക്രിയ. ഇതിന്റെ പ്രധാന ലക്ഷ്യം ബന്ധപ്പെട്ട വിഭവങ്ങളെയോ വിവരങ്ങളെയോ കൂടുതൽ കാര്യക്ഷമമായും സുരക്ഷിതമായും കൈകാര്യം ചെയ്യുകയാണ്. ശരിയായ രൂപകൽപ്പന നിയന്ത്രണം നിരീക്ഷണം സുരക്ഷാ നടപടികൾ എന്നിവ ഉപയോഗിക്കുന്നത് ഇതിന്റെ പ്രയോജനം വർധിപ്പിക്കുന്നു.','എൻക്രിപ്ഷൻ മനസ്സിലാക്കുമ്പോൾ അതിന്റെ നിർവചനം പ്രവർത്തനരീതി ഉപയോഗം ഗുണങ്ങൾ പരിമിതികൾ എന്നിവ പരിഗണിക്കണം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Long Answer','Hard',5,'ഡീക്രിപ്ഷൻ വിശദമായി വിശദീകരിക്കുക. നിർവചനം പ്രവർത്തനരീതി പ്രധാന പ്രയോജനങ്ങൾ പരിമിതികൾ എന്നിവ ഉൾപ്പെടുത്തുക.',ARRAY[]::text[],'ഡീക്രിപ്ഷൻ എന്നത് സംരക്ഷിത രൂപത്തിലുള്ള വിവരങ്ങളെ വായിക്കാവുന്ന രൂപത്തിലേക്ക് മാറ്റുന്ന പ്രക്രിയ. ഇതിന്റെ പ്രധാന ലക്ഷ്യം ബന്ധപ്പെട്ട വിഭവങ്ങളെയോ വിവരങ്ങളെയോ കൂടുതൽ കാര്യക്ഷമമായും സുരക്ഷിതമായും കൈകാര്യം ചെയ്യുകയാണ്. ശരിയായ രൂപകൽപ്പന നിയന്ത്രണം നിരീക്ഷണം സുരക്ഷാ നടപടികൾ എന്നിവ ഉപയോഗിക്കുന്നത് ഇതിന്റെ പ്രയോജനം വർധിപ്പിക്കുന്നു.','ഡീക്രിപ്ഷൻ മനസ്സിലാക്കുമ്പോൾ അതിന്റെ നിർവചനം പ്രവർത്തനരീതി ഉപയോഗം ഗുണങ്ങൾ പരിമിതികൾ എന്നിവ പരിഗണിക്കണം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Long Answer','Hard',5,'ഹാഷിംഗ് വിശദമായി വിശദീകരിക്കുക. നിർവചനം പ്രവർത്തനരീതി പ്രധാന പ്രയോജനങ്ങൾ പരിമിതികൾ എന്നിവ ഉൾപ്പെടുത്തുക.',ARRAY[]::text[],'ഹാഷിംഗ് എന്നത് ഡാറ്റയ്ക്ക് നിശ്ചിത നീളത്തിലുള്ള പ്രതിനിധി മൂല്യം സൃഷ്ടിക്കുന്ന ഏകദിശാ രീതി. ഇതിന്റെ പ്രധാന ലക്ഷ്യം ബന്ധപ്പെട്ട വിഭവങ്ങളെയോ വിവരങ്ങളെയോ കൂടുതൽ കാര്യക്ഷമമായും സുരക്ഷിതമായും കൈകാര്യം ചെയ്യുകയാണ്. ശരിയായ രൂപകൽപ്പന നിയന്ത്രണം നിരീക്ഷണം സുരക്ഷാ നടപടികൾ എന്നിവ ഉപയോഗിക്കുന്നത് ഇതിന്റെ പ്രയോജനം വർധിപ്പിക്കുന്നു.','ഹാഷിംഗ് മനസ്സിലാക്കുമ്പോൾ അതിന്റെ നിർവചനം പ്രവർത്തനരീതി ഉപയോഗം ഗുണങ്ങൾ പരിമിതികൾ എന്നിവ പരിഗണിക്കണം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Long Answer','Hard',5,'ഡിജിറ്റൽ ഒപ്പ് വിശദമായി വിശദീകരിക്കുക. നിർവചനം പ്രവർത്തനരീതി പ്രധാന പ്രയോജനങ്ങൾ പരിമിതികൾ എന്നിവ ഉൾപ്പെടുത്തുക.',ARRAY[]::text[],'ഡിജിറ്റൽ ഒപ്പ് എന്നത് ഡിജിറ്റൽ രേഖയുടെ ഉറവിടവും സമഗ്രതയും പരിശോധിക്കാൻ ഉപയോഗിക്കുന്ന സുരക്ഷാ രീതി. ഇതിന്റെ പ്രധാന ലക്ഷ്യം ബന്ധപ്പെട്ട വിഭവങ്ങളെയോ വിവരങ്ങളെയോ കൂടുതൽ കാര്യക്ഷമമായും സുരക്ഷിതമായും കൈകാര്യം ചെയ്യുകയാണ്. ശരിയായ രൂപകൽപ്പന നിയന്ത്രണം നിരീക്ഷണം സുരക്ഷാ നടപടികൾ എന്നിവ ഉപയോഗിക്കുന്നത് ഇതിന്റെ പ്രയോജനം വർധിപ്പിക്കുന്നു.','ഡിജിറ്റൽ ഒപ്പ് മനസ്സിലാക്കുമ്പോൾ അതിന്റെ നിർവചനം പ്രവർത്തനരീതി ഉപയോഗം ഗുണങ്ങൾ പരിമിതികൾ എന്നിവ പരിഗണിക്കണം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Long Answer','Hard',5,'സർട്ടിഫിക്കറ്റ് വിശദമായി വിശദീകരിക്കുക. നിർവചനം പ്രവർത്തനരീതി പ്രധാന പ്രയോജനങ്ങൾ പരിമിതികൾ എന്നിവ ഉൾപ്പെടുത്തുക.',ARRAY[]::text[],'സർട്ടിഫിക്കറ്റ് എന്നത് ഡിജിറ്റൽ തിരിച്ചറിയലുമായി ബന്ധപ്പെട്ട വിശ്വാസയോഗ്യമായ രേഖ. ഇതിന്റെ പ്രധാന ലക്ഷ്യം ബന്ധപ്പെട്ട വിഭവങ്ങളെയോ വിവരങ്ങളെയോ കൂടുതൽ കാര്യക്ഷമമായും സുരക്ഷിതമായും കൈകാര്യം ചെയ്യുകയാണ്. ശരിയായ രൂപകൽപ്പന നിയന്ത്രണം നിരീക്ഷണം സുരക്ഷാ നടപടികൾ എന്നിവ ഉപയോഗിക്കുന്നത് ഇതിന്റെ പ്രയോജനം വർധിപ്പിക്കുന്നു.','സർട്ടിഫിക്കറ്റ് മനസ്സിലാക്കുമ്പോൾ അതിന്റെ നിർവചനം പ്രവർത്തനരീതി ഉപയോഗം ഗുണങ്ങൾ പരിമിതികൾ എന്നിവ പരിഗണിക്കണം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Long Answer','Hard',5,'സുരക്ഷാ ദൗർബല്യം വിശദമായി വിശദീകരിക്കുക. നിർവചനം പ്രവർത്തനരീതി പ്രധാന പ്രയോജനങ്ങൾ പരിമിതികൾ എന്നിവ ഉൾപ്പെടുത്തുക.',ARRAY[]::text[],'സുരക്ഷാ ദൗർബല്യം എന്നത് ഒരു സംവിധാനത്തെ ആക്രമണത്തിന് വിധേയമാക്കാവുന്ന ബലഹീനത. ഇതിന്റെ പ്രധാന ലക്ഷ്യം ബന്ധപ്പെട്ട വിഭവങ്ങളെയോ വിവരങ്ങളെയോ കൂടുതൽ കാര്യക്ഷമമായും സുരക്ഷിതമായും കൈകാര്യം ചെയ്യുകയാണ്. ശരിയായ രൂപകൽപ്പന നിയന്ത്രണം നിരീക്ഷണം സുരക്ഷാ നടപടികൾ എന്നിവ ഉപയോഗിക്കുന്നത് ഇതിന്റെ പ്രയോജനം വർധിപ്പിക്കുന്നു.','സുരക്ഷാ ദൗർബല്യം മനസ്സിലാക്കുമ്പോൾ അതിന്റെ നിർവചനം പ്രവർത്തനരീതി ഉപയോഗം ഗുണങ്ങൾ പരിമിതികൾ എന്നിവ പരിഗണിക്കണം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Long Answer','Hard',5,'ഭീഷണി വിശദമായി വിശദീകരിക്കുക. നിർവചനം പ്രവർത്തനരീതി പ്രധാന പ്രയോജനങ്ങൾ പരിമിതികൾ എന്നിവ ഉൾപ്പെടുത്തുക.',ARRAY[]::text[],'ഭീഷണി എന്നത് സുരക്ഷയ്ക്ക് ദോഷം വരുത്താൻ സാധ്യതയുള്ള സാഹചര്യമോ പ്രവർത്തനമോ. ഇതിന്റെ പ്രധാന ലക്ഷ്യം ബന്ധപ്പെട്ട വിഭവങ്ങളെയോ വിവരങ്ങളെയോ കൂടുതൽ കാര്യക്ഷമമായും സുരക്ഷിതമായും കൈകാര്യം ചെയ്യുകയാണ്. ശരിയായ രൂപകൽപ്പന നിയന്ത്രണം നിരീക്ഷണം സുരക്ഷാ നടപടികൾ എന്നിവ ഉപയോഗിക്കുന്നത് ഇതിന്റെ പ്രയോജനം വർധിപ്പിക്കുന്നു.','ഭീഷണി മനസ്സിലാക്കുമ്പോൾ അതിന്റെ നിർവചനം പ്രവർത്തനരീതി ഉപയോഗം ഗുണങ്ങൾ പരിമിതികൾ എന്നിവ പരിഗണിക്കണം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Long Answer','Hard',5,'അപകടസാധ്യത വിശദമായി വിശദീകരിക്കുക. നിർവചനം പ്രവർത്തനരീതി പ്രധാന പ്രയോജനങ്ങൾ പരിമിതികൾ എന്നിവ ഉൾപ്പെടുത്തുക.',ARRAY[]::text[],'അപകടസാധ്യത എന്നത് ഒരു ഭീഷണി ദൗർബല്യം ഉപയോഗപ്പെടുത്തുന്നതിലൂടെ ഉണ്ടാകാവുന്ന നഷ്ടസാധ്യത. ഇതിന്റെ പ്രധാന ലക്ഷ്യം ബന്ധപ്പെട്ട വിഭവങ്ങളെയോ വിവരങ്ങളെയോ കൂടുതൽ കാര്യക്ഷമമായും സുരക്ഷിതമായും കൈകാര്യം ചെയ്യുകയാണ്. ശരിയായ രൂപകൽപ്പന നിയന്ത്രണം നിരീക്ഷണം സുരക്ഷാ നടപടികൾ എന്നിവ ഉപയോഗിക്കുന്നത് ഇതിന്റെ പ്രയോജനം വർധിപ്പിക്കുന്നു.','അപകടസാധ്യത മനസ്സിലാക്കുമ്പോൾ അതിന്റെ നിർവചനം പ്രവർത്തനരീതി ഉപയോഗം ഗുണങ്ങൾ പരിമിതികൾ എന്നിവ പരിഗണിക്കണം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Long Answer','Hard',5,'സുരക്ഷാ പരിശോധന വിശദമായി വിശദീകരിക്കുക. നിർവചനം പ്രവർത്തനരീതി പ്രധാന പ്രയോജനങ്ങൾ പരിമിതികൾ എന്നിവ ഉൾപ്പെടുത്തുക.',ARRAY[]::text[],'സുരക്ഷാ പരിശോധന എന്നത് സംവിധാനത്തിലെ ദൗർബല്യങ്ങൾ കണ്ടെത്തുന്നതിനുള്ള ക്രമബദ്ധമായ പരിശോധന. ഇതിന്റെ പ്രധാന ലക്ഷ്യം ബന്ധപ്പെട്ട വിഭവങ്ങളെയോ വിവരങ്ങളെയോ കൂടുതൽ കാര്യക്ഷമമായും സുരക്ഷിതമായും കൈകാര്യം ചെയ്യുകയാണ്. ശരിയായ രൂപകൽപ്പന നിയന്ത്രണം നിരീക്ഷണം സുരക്ഷാ നടപടികൾ എന്നിവ ഉപയോഗിക്കുന്നത് ഇതിന്റെ പ്രയോജനം വർധിപ്പിക്കുന്നു.','സുരക്ഷാ പരിശോധന മനസ്സിലാക്കുമ്പോൾ അതിന്റെ നിർവചനം പ്രവർത്തനരീതി ഉപയോഗം ഗുണങ്ങൾ പരിമിതികൾ എന്നിവ പരിഗണിക്കണം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Long Answer','Hard',5,'പ്രവേശന പരിശോധന വിശദമായി വിശദീകരിക്കുക. നിർവചനം പ്രവർത്തനരീതി പ്രധാന പ്രയോജനങ്ങൾ പരിമിതികൾ എന്നിവ ഉൾപ്പെടുത്തുക.',ARRAY[]::text[],'പ്രവേശന പരിശോധന എന്നത് സുരക്ഷാ നിയന്ത്രണങ്ങളെ പരീക്ഷിക്കാൻ അനുമതിയോടെ നടത്തുന്ന ആക്രമണ മാതൃകാ പരിശോധന. ഇതിന്റെ പ്രധാന ലക്ഷ്യം ബന്ധപ്പെട്ട വിഭവങ്ങളെയോ വിവരങ്ങളെയോ കൂടുതൽ കാര്യക്ഷമമായും സുരക്ഷിതമായും കൈകാര്യം ചെയ്യുകയാണ്. ശരിയായ രൂപകൽപ്പന നിയന്ത്രണം നിരീക്ഷണം സുരക്ഷാ നടപടികൾ എന്നിവ ഉപയോഗിക്കുന്നത് ഇതിന്റെ പ്രയോജനം വർധിപ്പിക്കുന്നു.','പ്രവേശന പരിശോധന മനസ്സിലാക്കുമ്പോൾ അതിന്റെ നിർവചനം പ്രവർത്തനരീതി ഉപയോഗം ഗുണങ്ങൾ പരിമിതികൾ എന്നിവ പരിഗണിക്കണം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Long Answer','Hard',5,'ലോഗ് നിരീക്ഷണം വിശദമായി വിശദീകരിക്കുക. നിർവചനം പ്രവർത്തനരീതി പ്രധാന പ്രയോജനങ്ങൾ പരിമിതികൾ എന്നിവ ഉൾപ്പെടുത്തുക.',ARRAY[]::text[],'ലോഗ് നിരീക്ഷണം എന്നത് സംവിധാന പ്രവർത്തനങ്ങളുടെ രേഖകൾ പരിശോധിച്ച് അസാധാരണത കണ്ടെത്തുന്ന പ്രവർത്തനം. ഇതിന്റെ പ്രധാന ലക്ഷ്യം ബന്ധപ്പെട്ട വിഭവങ്ങളെയോ വിവരങ്ങളെയോ കൂടുതൽ കാര്യക്ഷമമായും സുരക്ഷിതമായും കൈകാര്യം ചെയ്യുകയാണ്. ശരിയായ രൂപകൽപ്പന നിയന്ത്രണം നിരീക്ഷണം സുരക്ഷാ നടപടികൾ എന്നിവ ഉപയോഗിക്കുന്നത് ഇതിന്റെ പ്രയോജനം വർധിപ്പിക്കുന്നു.','ലോഗ് നിരീക്ഷണം മനസ്സിലാക്കുമ്പോൾ അതിന്റെ നിർവചനം പ്രവർത്തനരീതി ഉപയോഗം ഗുണങ്ങൾ പരിമിതികൾ എന്നിവ പരിഗണിക്കണം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Long Answer','Hard',5,'സംഭവ പ്രതികരണം വിശദമായി വിശദീകരിക്കുക. നിർവചനം പ്രവർത്തനരീതി പ്രധാന പ്രയോജനങ്ങൾ പരിമിതികൾ എന്നിവ ഉൾപ്പെടുത്തുക.',ARRAY[]::text[],'സംഭവ പ്രതികരണം എന്നത് സുരക്ഷാ സംഭവത്തെ തിരിച്ചറിഞ്ഞ് നിയന്ത്രിക്കുകയും പരിഹരിക്കുകയും ചെയ്യുന്ന പ്രക്രിയ. ഇതിന്റെ പ്രധാന ലക്ഷ്യം ബന്ധപ്പെട്ട വിഭവങ്ങളെയോ വിവരങ്ങളെയോ കൂടുതൽ കാര്യക്ഷമമായും സുരക്ഷിതമായും കൈകാര്യം ചെയ്യുകയാണ്. ശരിയായ രൂപകൽപ്പന നിയന്ത്രണം നിരീക്ഷണം സുരക്ഷാ നടപടികൾ എന്നിവ ഉപയോഗിക്കുന്നത് ഇതിന്റെ പ്രയോജനം വർധിപ്പിക്കുന്നു.','സംഭവ പ്രതികരണം മനസ്സിലാക്കുമ്പോൾ അതിന്റെ നിർവചനം പ്രവർത്തനരീതി ഉപയോഗം ഗുണങ്ങൾ പരിമിതികൾ എന്നിവ പരിഗണിക്കണം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Long Answer','Hard',5,'ഡാറ്റ ചോർച്ച വിശദമായി വിശദീകരിക്കുക. നിർവചനം പ്രവർത്തനരീതി പ്രധാന പ്രയോജനങ്ങൾ പരിമിതികൾ എന്നിവ ഉൾപ്പെടുത്തുക.',ARRAY[]::text[],'ഡാറ്റ ചോർച്ച എന്നത് അനുമതിയില്ലാത്ത വ്യക്തികൾക്ക് സംരക്ഷിത വിവരങ്ങൾ ലഭിക്കുന്ന സംഭവം. ഇതിന്റെ പ്രധാന ലക്ഷ്യം ബന്ധപ്പെട്ട വിഭവങ്ങളെയോ വിവരങ്ങളെയോ കൂടുതൽ കാര്യക്ഷമമായും സുരക്ഷിതമായും കൈകാര്യം ചെയ്യുകയാണ്. ശരിയായ രൂപകൽപ്പന നിയന്ത്രണം നിരീക്ഷണം സുരക്ഷാ നടപടികൾ എന്നിവ ഉപയോഗിക്കുന്നത് ഇതിന്റെ പ്രയോജനം വർധിപ്പിക്കുന്നു.','ഡാറ്റ ചോർച്ച മനസ്സിലാക്കുമ്പോൾ അതിന്റെ നിർവചനം പ്രവർത്തനരീതി ഉപയോഗം ഗുണങ്ങൾ പരിമിതികൾ എന്നിവ പരിഗണിക്കണം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Long Answer','Hard',5,'ബാക്കപ്പ് വിശദമായി വിശദീകരിക്കുക. നിർവചനം പ്രവർത്തനരീതി പ്രധാന പ്രയോജനങ്ങൾ പരിമിതികൾ എന്നിവ ഉൾപ്പെടുത്തുക.',ARRAY[]::text[],'ബാക്കപ്പ് എന്നത് നഷ്ടപ്പെട്ട ഡാറ്റ വീണ്ടെടുക്കുന്നതിനായി സൂക്ഷിക്കുന്ന പകർപ്പ്. ഇതിന്റെ പ്രധാന ലക്ഷ്യം ബന്ധപ്പെട്ട വിഭവങ്ങളെയോ വിവരങ്ങളെയോ കൂടുതൽ കാര്യക്ഷമമായും സുരക്ഷിതമായും കൈകാര്യം ചെയ്യുകയാണ്. ശരിയായ രൂപകൽപ്പന നിയന്ത്രണം നിരീക്ഷണം സുരക്ഷാ നടപടികൾ എന്നിവ ഉപയോഗിക്കുന്നത് ഇതിന്റെ പ്രയോജനം വർധിപ്പിക്കുന്നു.','ബാക്കപ്പ് മനസ്സിലാക്കുമ്പോൾ അതിന്റെ നിർവചനം പ്രവർത്തനരീതി ഉപയോഗം ഗുണങ്ങൾ പരിമിതികൾ എന്നിവ പരിഗണിക്കണം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Long Answer','Hard',5,'ദുരന്ത വീണ്ടെടുക്കൽ വിശദമായി വിശദീകരിക്കുക. നിർവചനം പ്രവർത്തനരീതി പ്രധാന പ്രയോജനങ്ങൾ പരിമിതികൾ എന്നിവ ഉൾപ്പെടുത്തുക.',ARRAY[]::text[],'ദുരന്ത വീണ്ടെടുക്കൽ എന്നത് വലിയ സുരക്ഷാ സംഭവത്തിന് ശേഷം സംവിധാനങ്ങളെ പുനഃസ്ഥാപിക്കുന്ന പദ്ധതി. ഇതിന്റെ പ്രധാന ലക്ഷ്യം ബന്ധപ്പെട്ട വിഭവങ്ങളെയോ വിവരങ്ങളെയോ കൂടുതൽ കാര്യക്ഷമമായും സുരക്ഷിതമായും കൈകാര്യം ചെയ്യുകയാണ്. ശരിയായ രൂപകൽപ്പന നിയന്ത്രണം നിരീക്ഷണം സുരക്ഷാ നടപടികൾ എന്നിവ ഉപയോഗിക്കുന്നത് ഇതിന്റെ പ്രയോജനം വർധിപ്പിക്കുന്നു.','ദുരന്ത വീണ്ടെടുക്കൽ മനസ്സിലാക്കുമ്പോൾ അതിന്റെ നിർവചനം പ്രവർത്തനരീതി ഉപയോഗം ഗുണങ്ങൾ പരിമിതികൾ എന്നിവ പരിഗണിക്കണം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Long Answer','Hard',5,'സുരക്ഷാ ബോധവൽക്കരണം വിശദമായി വിശദീകരിക്കുക. നിർവചനം പ്രവർത്തനരീതി പ്രധാന പ്രയോജനങ്ങൾ പരിമിതികൾ എന്നിവ ഉൾപ്പെടുത്തുക.',ARRAY[]::text[],'സുരക്ഷാ ബോധവൽക്കരണം എന്നത് ഉപയോക്താക്കളെ സുരക്ഷിതമായ ഡിജിറ്റൽ പെരുമാറ്റത്തെക്കുറിച്ച് പരിശീലിപ്പിക്കുന്ന പ്രവർത്തനം. ഇതിന്റെ പ്രധാന ലക്ഷ്യം ബന്ധപ്പെട്ട വിഭവങ്ങളെയോ വിവരങ്ങളെയോ കൂടുതൽ കാര്യക്ഷമമായും സുരക്ഷിതമായും കൈകാര്യം ചെയ്യുകയാണ്. ശരിയായ രൂപകൽപ്പന നിയന്ത്രണം നിരീക്ഷണം സുരക്ഷാ നടപടികൾ എന്നിവ ഉപയോഗിക്കുന്നത് ഇതിന്റെ പ്രയോജനം വർധിപ്പിക്കുന്നു.','സുരക്ഷാ ബോധവൽക്കരണം മനസ്സിലാക്കുമ്പോൾ അതിന്റെ നിർവചനം പ്രവർത്തനരീതി ഉപയോഗം ഗുണങ്ങൾ പരിമിതികൾ എന്നിവ പരിഗണിക്കണം.');
INSERT INTO question_bank (subject, language, question_type, difficulty, marks, question, options, correct_answer, explanation) VALUES ('MAL-Cyber Security','മലയാളം','Long Answer','Hard',5,'സുരക്ഷാ നയം വിശദമായി വിശദീകരിക്കുക. നിർവചനം പ്രവർത്തനരീതി പ്രധാന പ്രയോജനങ്ങൾ പരിമിതികൾ എന്നിവ ഉൾപ്പെടുത്തുക.',ARRAY[]::text[],'സുരക്ഷാ നയം എന്നത് ഒരു സ്ഥാപനത്തിന്റെ സുരക്ഷാ നിയമങ്ങളും ഉത്തരവാദിത്തങ്ങളും വ്യക്തമാക്കുന്ന രേഖ. ഇതിന്റെ പ്രധാന ലക്ഷ്യം ബന്ധപ്പെട്ട വിഭവങ്ങളെയോ വിവരങ്ങളെയോ കൂടുതൽ കാര്യക്ഷമമായും സുരക്ഷിതമായും കൈകാര്യം ചെയ്യുകയാണ്. ശരിയായ രൂപകൽപ്പന നിയന്ത്രണം നിരീക്ഷണം സുരക്ഷാ നടപടികൾ എന്നിവ ഉപയോഗിക്കുന്നത് ഇതിന്റെ പ്രയോജനം വർധിപ്പിക്കുന്നു.','സുരക്ഷാ നയം മനസ്സിലാക്കുമ്പോൾ അതിന്റെ നിർവചനം പ്രവർത്തനരീതി ഉപയോഗം ഗുണങ്ങൾ പരിമിതികൾ എന്നിവ പരിഗണിക്കണം.');
